/**
 * バイタル管理システム Backend for Google Sheets
 * 
 * 設定手順:
 * 1. Googleスプレッドシートを作成し、以下のシート名を用意します。
 *    - 「Database」: カラム A:日付, B:利用者名, C:体温, D:最高血圧, E:最低血圧, F:脈拍, G:SpO2, H:食事朝主, I:食事朝副, J:食事昼主, K:食事昼副, L:食事晩主, M:食事晩副, N:排便, O:備考
 * 2. 拡張機能 > Apps Script を開き、このコードを貼り付けます。
 * 3. デプロイ > 新しいデプロイ > 種類:Webアプリ としてデプロイします。
 */

function doGet(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const dbSheet = ss.getSheetByName('Database');
  const data = dbSheet.getDataRange().getValues();

  // ヘッダーを除いたデータをJSONで返す
  const headers = data[0];
  const rows = data.slice(1).map(row => {
    let obj = {};
    headers.forEach((header, i) => {
      obj[header] = row[i];
    });
    return obj;
  });

  return ContentService.createTextOutput(JSON.stringify(rows))
    .setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  try {
    const params = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const dbSheet = ss.getSheetByName('Database');

    // まとめて追記
    const rowsToAdd = params.map(record => [
      record.date,
      record.residentName,
      record.temperature,
      record.systolic,
      record.diastolic,
      record.pulse,
      record.spo2,
      record.mealMorning.main,
      record.mealMorning.side,
      record.mealNoon.main,
      record.mealNoon.side,
      record.mealNight.main,
      record.mealNight.side,
      record.bowelCount,
      record.note
    ]);

    dbSheet.getRange(dbSheet.getLastRow() + 1, 1, rowsToAdd.length, rowsToAdd[0].length).setValues(rowsToAdd);

    return ContentService.createTextOutput(JSON.stringify({ status: 'success', count: rowsToAdd.length }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

import React, { useState } from 'react';
import { MOCK_RESIDENTS, THRESHOLDS } from '../constants';
import { VitalRecord, Meal } from '../types';
import { Save, AlertCircle, Calendar } from 'lucide-react';

interface BatchInputTableProps {
  onSave: (records: VitalRecord[]) => void;
}

const BatchInputTable: React.FC<BatchInputTableProps> = ({ onSave }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [data, setData] = useState<Record<string, Partial<VitalRecord>>>(() => {
    const initial: Record<string, Partial<VitalRecord>> = {};
    MOCK_RESIDENTS.forEach(res => {
      initial[res.id] = {
        residentId: res.id,
        residentName: res.name,
        date: '',
        temperature: '',
        systolic: '',
        diastolic: '',
        pulse: '',
        spo2: '',
        mealMorning: { main: 10, side: 10 },
        mealNoon: { main: 10, side: 10 },
        mealNight: { main: 10, side: 10 },
        bowelCount: '0',
        note: ''
      };
    });
    return initial;
  });

  const handleChange = (resId: string, field: keyof VitalRecord, value: any) => {
    setData(prev => ({
      ...prev,
      [resId]: { ...prev[resId], [field]: value }
    }));
  };

  const handleMealChange = (resId: string, time: 'mealMorning' | 'mealNoon' | 'mealNight', type: keyof Meal, value: number) => {
    const currentMeal = data[resId][time] as Meal;
    setData(prev => ({
      ...prev,
      [resId]: { 
        ...prev[resId], 
        [time]: { ...currentMeal, [type]: value }
      }
    }));
  };

  const handleSave = () => {
    // Fix: Spread types may only be created from object types.
    // Explicitly casting d to any to bypass inference issue with Object.values when spreading into a new object.
    const recordsToSave: VitalRecord[] = Object.values(data).map(d => ({
      ...(d as any),
      date: date,
    } as VitalRecord));
    onSave(recordsToSave);
  };

  // Helper to check for abnormal values
  const isAbnormal = (field: string, value: string) => {
    const num = parseFloat(value);
    if (isNaN(num)) return false;
    if (field === 'temperature' && num >= THRESHOLDS.TEMP_HIGH) return true;
    if (field === 'systolic' && num >= THRESHOLDS.BP_SYSTOLIC_HIGH) return true;
    if (field === 'diastolic' && num >= THRESHOLDS.BP_DIASTOLIC_HIGH) return true;
    if (field === 'spo2' && num < THRESHOLDS.SPO2_LOW) return true;
    return false;
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border">
        <div className="flex items-center gap-3">
          <Calendar className="text-blue-500" size={24} />
          <div>
            <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">記録日</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)}
              className="border rounded-md px-3 py-1.5 focus:ring-2 focus:ring-blue-500 outline-none text-slate-700 font-medium"
            />
          </div>
        </div>
        <button 
          onClick={handleSave}
          className="w-full sm:w-auto flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-lg font-semibold shadow-md transition-all active:scale-95"
        >
          <Save size={20} />
          一括登録を実行
        </button>
      </div>

      <div className="overflow-x-auto rounded-xl shadow-sm border border-slate-200 bg-white">
        <table className="min-w-full divide-y divide-slate-200 text-sm">
          <thead className="bg-slate-50">
            <tr>
              <th className="px-3 py-3 text-left font-semibold text-slate-600 sticky left-0 bg-slate-50 z-10 w-40">氏名</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-24">体温</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-36">血圧 (上/下)</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-20">脈拍</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-20">SpO2</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600">食事量 (朝/昼/晩)</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-20">排便</th>
              <th className="px-2 py-3 text-left font-semibold text-slate-600 min-w-[150px]">備考</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200">
            {MOCK_RESIDENTS.map((res) => (
              <tr key={res.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-3 py-2 font-medium text-slate-800 sticky left-0 bg-white z-10 border-r border-slate-100">
                  <div className="flex flex-col">
                    <span className="text-xs text-slate-400 font-normal">#{res.roomNumber}</span>
                    <span>{res.name}</span>
                  </div>
                </td>
                <td className="px-2 py-2">
                  <input
                    type="number"
                    placeholder="36.5"
                    step="0.1"
                    className={`w-full text-center border rounded py-1.5 focus:ring-1 outline-none ${
                      isAbnormal('temperature', data[res.id].temperature || '') ? 'bg-red-50 border-red-300 text-red-600 animate-pulse' : 'border-slate-300'
                    }`}
                    value={data[res.id].temperature}
                    onChange={(e) => handleChange(res.id, 'temperature', e.target.value)}
                  />
                </td>
                <td className="px-2 py-2">
                  <div className="flex items-center gap-1">
                    <input
                      type="number"
                      placeholder="120"
                      className={`w-full text-center border rounded py-1.5 focus:ring-1 outline-none ${
                        isAbnormal('systolic', data[res.id].systolic || '') ? 'bg-red-50 border-red-300 text-red-600' : 'border-slate-300'
                      }`}
                      value={data[res.id].systolic}
                      onChange={(e) => handleChange(res.id, 'systolic', e.target.value)}
                    />
                    <span className="text-slate-400">/</span>
                    <input
                      type="number"
                      placeholder="80"
                      className={`w-full text-center border rounded py-1.5 focus:ring-1 outline-none ${
                        isAbnormal('diastolic', data[res.id].diastolic || '') ? 'bg-red-50 border-red-300 text-red-600' : 'border-slate-300'
                      }`}
                      value={data[res.id].diastolic}
                      onChange={(e) => handleChange(res.id, 'diastolic', e.target.value)}
                    />
                  </div>
                </td>
                <td className="px-2 py-2">
                  <input
                    type="number"
                    placeholder="70"
                    className="w-full text-center border border-slate-300 rounded py-1.5 focus:ring-1 outline-none"
                    value={data[res.id].pulse}
                    onChange={(e) => handleChange(res.id, 'pulse', e.target.value)}
                  />
                </td>
                <td className="px-2 py-2">
                  <input
                    type="number"
                    placeholder="98"
                    className={`w-full text-center border rounded py-1.5 focus:ring-1 outline-none ${
                      isAbnormal('spo2', data[res.id].spo2 || '') ? 'bg-red-50 border-red-300 text-red-600 font-bold' : 'border-slate-300'
                    }`}
                    value={data[res.id].spo2}
                    onChange={(e) => handleChange(res.id, 'spo2', e.target.value)}
                  />
                </td>
                <td className="px-2 py-2">
                  <div className="flex gap-2 justify-center">
                    {['mealMorning', 'mealNoon', 'mealNight'].map((time) => (
                      <div key={time} className="flex flex-col items-center gap-1 border border-slate-100 p-1 rounded bg-slate-50">
                        <span className="text-[10px] text-slate-400">
                          {time === 'mealMorning' ? '朝' : time === 'mealNoon' ? '昼' : '晩'}
                        </span>
                        <div className="flex gap-1">
                          <input
                            type="number"
                            min="0"
                            max="10"
                            className="w-8 text-center text-xs border rounded p-0.5"
                            value={(data[res.id][time as keyof VitalRecord] as Meal).main}
                            onChange={(e) => handleMealChange(res.id, time as any, 'main', parseInt(e.target.value))}
                          />
                          <input
                            type="number"
                            min="0"
                            max="10"
                            className="w-8 text-center text-xs border border-blue-200 rounded p-0.5 bg-blue-50"
                            value={(data[res.id][time as keyof VitalRecord] as Meal).side}
                            onChange={(e) => handleMealChange(res.id, time as any, 'side', parseInt(e.target.value))}
                          />
                        </div>
                      </div>
                    ))}
                  </div>
                </td>
                <td className="px-2 py-2">
                  <input
                    type="text"
                    placeholder="1"
                    className="w-full text-center border border-slate-300 rounded py-1.5 focus:ring-1 outline-none"
                    value={data[res.id].bowelCount}
                    onChange={(e) => handleChange(res.id, 'bowelCount', e.target.value)}
                  />
                </td>
                <td className="px-2 py-2">
                  <input
                    type="text"
                    placeholder="備考を入力..."
                    className="w-full border border-slate-300 rounded py-1.5 px-2 focus:ring-1 outline-none text-xs"
                    value={data[res.id].note}
                    onChange={(e) => handleChange(res.id, 'note', e.target.value)}
                  />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="flex justify-center pb-8 no-print">
         <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-start gap-3 max-w-2xl">
           <AlertCircle className="text-blue-500 mt-0.5 shrink-0" size={20} />
           <p className="text-xs text-blue-700 leading-relaxed">
             入力が完了したら右上の「一括登録」ボタンを押してください。異常値（体温37.5℃以上、血圧160以上など）は自動的に赤く強調されます。SpO2が94%以下の場合は呼吸状態に注意が必要です。
           </p>
         </div>
      </div>
    </div>
  );
};

