            <BatchInputTable onSave={saveBatchRecords} residents={residents} records={records} />
          )}
          {currentView === AppView.INDIVIDUAL_HISTORY && (
            <IndividualHistory records={records} residents={residents} />
          )}
          {currentView === AppView.DASHBOARD && (
            <Dashboard records={records} />
          )}
          {currentView === AppView.RESIDENT_MASTER && (
            <ResidentMaster residents={residents} onUpdate={updateResidents} />
          )}
        </div>
      </main>

      <footer className="bg-white border-t py-4 text-center text-xs text-slate-400 no-print">
        &copy; 2024 VitalSign Pro - 介護現場効率化システム
      </footer>
    </div>
  );
};

