import React, { useState } from 'react';
import { Resident } from '../types';
import { Plus, Trash2, Save, UserCheck } from 'lucide-react';

interface ResidentMasterProps {
  residents: Resident[];
  onUpdate: (residents: Resident[]) => void;
}

const ResidentMaster: React.FC<ResidentMasterProps> = ({ residents, onUpdate }) => {
  const [localResidents, setLocalResidents] = useState<Resident[]>(residents);

  const handleUpdate = (id: string, field: keyof Resident, value: string) => {
    setLocalResidents(prev => prev.map(r => r.id === id ? { ...r, [field]: value } : r));
  };

  const handleAdd = () => {
    const newId = `res-${Date.now()}`;
    setLocalResidents(prev => [...prev, { id: newId, name: '新規利用者', roomNumber: '100' }]);
  };

  const handleRemove = (id: string) => {
    if (confirm('この利用者を削除しますか？')) {
      setLocalResidents(prev => prev.filter(r => r.id !== id));
    }
  };

  const handleSave = () => {
    onUpdate(localResidents);
    alert('マスタ情報を更新しました。');
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-xl border shadow-sm flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800">利用者マスタ設定</h2>
          <p className="text-sm text-slate-500">入所者の氏名と居室番号を編集できます。</p>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={handleAdd}
            className="flex items-center gap-2 bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2 rounded-lg font-semibold transition-all"
          >
            <Plus size={18} />
            追加
          </button>
          <button 
            onClick={handleSave}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-semibold transition-all shadow-md"
          >
            <Save size={18} />
            マスタを保存
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl border shadow-sm overflow-hidden">
        <table className="min-w-full divide-y divide-slate-200">
          <thead className="bg-slate-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider w-32">居室番号</th>
              <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">氏名</th>
              <th className="px-6 py-3 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider w-20">操作</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-slate-200">
            {localResidents.map((res) => (
              <tr key={res.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-3 whitespace-nowrap">
                  <input 
                    type="text" 
                    value={res.roomNumber}
                    onChange={(e) => handleUpdate(res.id, 'roomNumber', e.target.value)}
                    className="w-full border rounded px-2 py-1 text-sm focus:ring-1 focus:ring-blue-500 outline-none"
                  />
                </td>
                <td className="px-6 py-3 whitespace-nowrap">
                  <input 
                    type="text" 
                    value={res.name}
                    onChange={(e) => handleUpdate(res.id, 'name', e.target.value)}
                    className="w-full border rounded px-2 py-1 text-sm focus:ring-1 focus:ring-blue-500 outline-none"
                  />
                </td>
                <td className="px-6 py-3 whitespace-nowrap text-right">
                  <button 
                    onClick={() => handleRemove(res.id)}
                    className="text-slate-400 hover:text-red-500 transition-colors"
                  >
                    <Trash2 size={18} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {localResidents.length === 0 && (
          <div className="py-20 text-center text-slate-400">
             <UserCheck size={48} className="mx-auto mb-4 opacity-20" />
             <p>利用者が登録されていません。</p>
          </div>
        )}
      </div>
    </div>
  );
};

