                        }`}
                        value={rowData.spo2 || ''}
                        onChange={(e) => handleChange(res.id, 'spo2', e.target.value)}
                      />
                      {prev?.spo2 && (
                        <span className="absolute -bottom-1 left-0 right-0 text-center text-[8px] text-slate-300 pointer-events-none">
                          前:{prev.spo2}
                        </span>
