                  </td>
                  <td className="px-2 py-2">
                    <div className="flex gap-1 justify-center">
                      {['mealMorning', 'mealNoon', 'mealNight'].map((time) => {
                        const meal = (rowData[time as keyof VitalRecord] as Meal) || { main: 10, side: 10 };
                        return (
                          <div key={time} className="flex flex-col items-center gap-0.5 border border-slate-100 p-0.5 rounded bg-slate-50">
