                              />
                              <input
                                type="number"
                                inputMode="numeric"
                                min="0"
                                max="10"
                                className="w-7 text-center text-[10px] border border-blue-200 rounded p-0.5 bg-blue-50"
                                value={meal.side}
                                onChange={(e) => handleMealChange(res.id, time as any, 'side', parseInt(e.target.value) || 0)}
                              />
                            </div>
