                      })}
                    </div>
                  </td>
                  <td className="px-2 py-2">
                    <input
                      type="text"
                      inputMode="numeric"
                      placeholder="1"
                      className="w-full text-center border border-slate-300 rounded py-1.5 focus:ring-1 outline-none"
                      value={rowData.bowelCount || '0'}
