  const [residents, setResidents] = useState<Resident[]>(INITIAL_RESIDENTS);
  const [facilityName, setFacilityName] = useState<string>('陽光ケアホーム');

  useEffect(() => {
    const savedRecords = localStorage.getItem('vital_records');
    if (savedRecords) {
      setRecords(JSON.parse(savedRecords));
    }

    const savedResidents = localStorage.getItem('residents_master');
    if (savedResidents) {
      setResidents(JSON.parse(savedResidents));
    }

    const savedFacility = localStorage.getItem('facility_name');
    if (savedFacility) {
      setFacilityName(savedFacility);
    }
