import React, { useState, useEffect } from 'react';
import { Resident } from '../types';
import { Plus, Trash2, Save, UserCheck, Building } from 'lucide-react';

interface ResidentMasterProps {
  residents: Resident[];
  onUpdate: (residents: Resident[]) => void;
  facilityName: string;
  onFacilityNameUpdate: (name: string) => void;
}

const ResidentMaster: React.FC<ResidentMasterProps> = ({ 
  residents, 
  onUpdate, 
  facilityName, 
  onFacilityNameUpdate 
}) => {
  // ローカルステートで編集内容を保持
  const [localResidents, setLocalResidents] = useState<Resident[]>(residents);
  const [localFacilityName, setLocalFacilityName] = useState<string>(facilityName);

  // 親（App.tsx）のデータがロード・更新された場合にローカルステートを同期
  // これにより、初期読み込みの遅延や保存後の不整合を防ぎます
  useEffect(() => {
    setLocalResidents(residents);
  }, [residents]);

  useEffect(() => {
    setLocalFacilityName(facilityName);
  }, [facilityName]);

  const handleUpdate = (id: string, field: keyof Resident, value: string) => {
    setLocalResidents(prev => prev.map(r => r.id === id ? { ...r, [field]: value } : r));
  };

  const handleAdd = () => {
    const newId = `res-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    const newResident: Resident = { 
      id: newId, 
      name: '新規利用者', 
      roomNumber: '' 
    };
    setLocalResidents(prev => [...prev, newResident]);
  };

  const handleRemove = (id: string) => {
    if (window.confirm('この利用者をリストから削除しますか？\n（「設定を保存」を押すまで確定されません）')) {
      setLocalResidents(prev => prev.filter(r => r.id !== id));
    }
  };

  const handleSave = () => {
    // 空の名前などをチェック
    const hasEmptyName = localResidents.some(r => !r.name.trim());
    if (hasEmptyName) {
      if (!window.confirm('名前が空の利用者がいます。そのまま保存しますか？')) {
        return;
      }
    }

    onUpdate(localResidents);
    onFacilityNameUpdate(localFacilityName);
    alert('マスタ設定を保存しました。');
  };

  return (
    <div className="space-y-6">
      {/* System Settings Section */}
      <div className="bg-white p-6 rounded-xl border shadow-sm">
        <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2 mb-4">
          <Building size={20} className="text-blue-600" />
          施設基本設定
        </h2>
        <div className="max-w-md">
          <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">施設名称</label>
          <input 
            type="text" 
            value={localFacilityName}
            onChange={(e) => setLocalFacilityName(e.target.value)}
            placeholder="施設名を入力してください"
            className="w-full border rounded-md px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none font-medium"
          />
        </div>
      </div>

      {/* Resident Master Section */}
      <div className="bg-white p-6 rounded-xl border shadow-sm flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-800">利用者マスタ設定</h2>
          <p className="text-sm text-slate-500">入所者の氏名と居室番号を編集できます。</p>
        </div>
        <div className="flex gap-2 w-full sm:w-auto">
          <button 
            onClick={handleAdd}
            className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2.5 rounded-lg font-semibold transition-all active:scale-95"
          >
            <Plus size={18} />
            新規追加
          </button>
          <button 
            onClick={handleSave}
            className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-lg font-semibold transition-all shadow-md active:scale-95"
          >
            <Save size={18} />
            設定を保存
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl border shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider w-32">居室番号</th>
                <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">氏名</th>
                <th className="px-6 py-3 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider w-24">操作</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-slate-200">
              {localResidents.map((res) => (
                <tr key={res.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-3 whitespace-nowrap">
                    <input 
                      type="text" 
                      value={res.roomNumber}
                      placeholder="例: 101"
                      onChange={(e) => handleUpdate(res.id, 'roomNumber', e.target.value)}
                      className="w-full border border-slate-200 rounded px-2 py-1.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                    />
                  </td>
                  <td className="px-6 py-3 whitespace-nowrap">
                    <input 
                      type="text" 
                      value={res.name}
                      placeholder="氏名を入力"
                      onChange={(e) => handleUpdate(res.id, 'name', e.target.value)}
                      className="w-full border border-slate-200 rounded px-2 py-1.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                    />
                  </td>
                  <td className="px-6 py-3 whitespace-nowrap text-right">
                    <button 
                      onClick={() => handleRemove(res.id)}
                      title="削除"
                      className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-all"
                    >
                      <Trash2 size={18} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {localResidents.length === 0 && (
          <div className="py-20 text-center text-slate-400">
             <UserCheck size={48} className="mx-auto mb-4 opacity-20" />
             <p>利用者が登録されていません。「新規追加」で追加してください。</p>
          </div>
        )}
      </div>

      <div className="bg-amber-50 border border-amber-200 p-4 rounded-lg">
        <p className="text-xs text-amber-800 leading-relaxed">
          ※ 削除や追加を行った後は、必ず右上の<b>「設定を保存」</b>ボタンを押して確定させてください。保存せずに画面を切り替えると変更内容は破棄されます。
        </p>
      </div>
    </div>
  );
};

export default ResidentMaster;

import React, { useState, useMemo, useEffect } from 'react';
import { THRESHOLDS, DAYS_JP } from '../constants';
import { VitalRecord, Meal, Resident } from '../types';
import { Save, AlertCircle, Calendar } from 'lucide-react';

interface BatchInputTableProps {
  onSave: (records: VitalRecord[]) => void;
  residents: Resident[];
  records: VitalRecord[];
}

const BatchInputTable: React.FC<BatchInputTableProps> = ({ onSave, residents, records }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const [data, setData] = useState<Record<string, Partial<VitalRecord>>>(() => {
    const initial: Record<string, Partial<VitalRecord>> = {};
    residents.forEach(res => {
      initial[res.id] = {
        residentId: res.id,
        residentName: res.name,
        date: '',
        temperature: '',
        systolic: '',
        diastolic: '',
        pulse: '',
        spo2: '',
        mealMorning: { main: 10, side: 10 },
        mealNoon: { main: 10, side: 10 },
        mealNight: { main: 10, side: 10 },
        bowelCount: '0',
        note: ''
      };
    });
    return initial;
  });

  // Sync data state when residents list changes
  useEffect(() => {
    setData(prev => {
      const next = { ...prev };
      let changed = false;
      residents.forEach(res => {
        if (!next[res.id]) {
          next[res.id] = {
            residentId: res.id,
            residentName: res.name,
            temperature: '',
            systolic: '',
            diastolic: '',
            pulse: '',
            spo2: '',
            mealMorning: { main: 10, side: 10 },
            mealNoon: { main: 10, side: 10 },
            mealNight: { main: 10, side: 10 },
            bowelCount: '0',
            note: ''
          };
          changed = true;
        }
      });
      return changed ? next : prev;
    });
  }, [residents]);

  const formattedDateWithDay = useMemo(() => {
    const d = new Date(date);
    const day = DAYS_JP[d.getDay()];
    return `${date} (${day})`;
  }, [date]);

  // Map of last record per resident for reference
  const prevDataMap = useMemo(() => {
    const map: Record<string, VitalRecord> = {};
    const sorted = [...records].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    residents.forEach(res => {
      const last = sorted.find(r => r.residentId === res.id && r.date < date);
      if (last) map[res.id] = last;
    });
    return map;
  }, [records, date, residents]);

  const handleChange = (resId: string, field: keyof VitalRecord, value: any) => {
    setData(prev => ({
      ...prev,
      [resId]: { ...prev[resId], [field]: value }
    }));
  };

  const handleMealChange = (resId: string, time: 'mealMorning' | 'mealNoon' | 'mealNight', type: keyof Meal, value: number) => {
    setData(prev => {
      const row = prev[resId];
      if (!row) return prev;
      const currentMeal = (row[time] as Meal) || { main: 10, side: 10 };
      return {
        ...prev,
        [resId]: { 
          ...row, 
          [time]: { ...currentMeal, [type]: value }
        }
      };
    });
  };

  const handleSave = () => {
    const recordsToSave: VitalRecord[] = Object.values(data)
      .filter(d => d.residentId) // Ensure only valid entries are saved
      .map(d => ({
        ...(d as any),
        date: date,
      } as VitalRecord));
    onSave(recordsToSave);
  };

  const isAbnormal = (field: string, value: string) => {
    const num = parseFloat(value);
    if (isNaN(num)) return false;
    if (field === 'temperature' && num >= THRESHOLDS.TEMP_HIGH) return true;
    if (field === 'systolic' && num >= THRESHOLDS.BP_SYSTOLIC_HIGH) return true;
    if (field === 'diastolic' && num >= THRESHOLDS.BP_DIASTOLIC_HIGH) return true;
    if (field === 'spo2' && num < THRESHOLDS.SPO2_LOW) return true;
    if (field === 'pulse' && (num >= THRESHOLDS.PULSE_HIGH || num <= THRESHOLDS.PULSE_LOW)) return true;
    return false;
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border">
        <div className="flex items-center gap-3">
          <Calendar className="text-blue-500" size={24} />
          <div>
            <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">記録日: {formattedDateWithDay}</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)}
              className="border rounded-md px-3 py-1.5 focus:ring-2 focus:ring-blue-500 outline-none text-slate-700 font-medium"
            />
          </div>
        </div>
        <button 
          onClick={handleSave}
          className="w-full sm:w-auto flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-lg font-semibold shadow-md transition-all active:scale-95"
        >
          <Save size={20} />
          一括登録を実行
        </button>
      </div>

      <div className="overflow-x-auto rounded-xl shadow-sm border border-slate-200 bg-white">
        <table className="min-w-full divide-y divide-slate-200 text-sm">
          <thead className="bg-slate-50">
            <tr>
              <th className="px-3 py-3 text-left font-semibold text-slate-600 sticky left-0 bg-slate-50 z-10 w-40">氏名</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-28">体温</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-48">血圧 (上/下)</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-24">脈拍</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-24">SpO2</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600">食事量 (朝/昼/晩)</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-24">排便</th>
              <th className="px-2 py-3 text-left font-semibold text-slate-600 min-w-[300px]">備考</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200">
            {residents.map((res) => {
              const prev = prevDataMap[res.id];
              const rowData = data[res.id];

              if (!rowData) return null;

              return (
                <tr key={res.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-3 py-2 font-medium text-slate-800 sticky left-0 bg-white z-10 border-r border-slate-100">
                    <div className="flex flex-col">
                      <span className="text-[10px] text-slate-400 font-normal">#{res.roomNumber}</span>
                      <span className="truncate">{res.name}</span>
                    </div>
                  </td>
                  <td className="px-2 py-2">
                    <div className="relative pb-3">
                      <input
                        type="number"
                        inputMode="decimal"
                        placeholder="36.5"
                        step="0.1"
                        className={`w-full text-center border rounded py-1.5 px-1 focus:ring-1 outline-none font-medium ${
                          isAbnormal('temperature', rowData.temperature || '') ? 'bg-red-50 border-red-300 text-red-600 animate-pulse' : 'border-slate-300'
                        }`}
                        value={rowData.temperature || ''}
                        onChange={(e) => handleChange(res.id, 'temperature', e.target.value)}
                      />
                      {prev?.temperature && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[9px] text-slate-400 pointer-events-none truncate">
                          前:{prev.temperature}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-2">
                    <div className="relative pb-3">
                      <div className="flex items-center gap-1">
                        <input
                          type="number"
                          inputMode="numeric"
                          placeholder="120"
                          className={`w-full text-center border rounded py-1.5 px-1 focus:ring-1 outline-none font-medium ${
                            isAbnormal('systolic', rowData.systolic || '') ? 'bg-red-50 border-red-300 text-red-600' : 'border-slate-300'
                          }`}
                          value={rowData.systolic || ''}
                          onChange={(e) => handleChange(res.id, 'systolic', e.target.value)}
                        />
                        <span className="text-slate-400">/</span>
                        <input
                          type="number"
                          inputMode="numeric"
                          placeholder="80"
                          className={`w-full text-center border rounded py-1.5 px-1 focus:ring-1 outline-none font-medium ${
                            isAbnormal('diastolic', rowData.diastolic || '') ? 'bg-red-50 border-red-300 text-red-600' : 'border-slate-300'
                          }`}
                          value={rowData.diastolic || ''}
                          onChange={(e) => handleChange(res.id, 'diastolic', e.target.value)}
                        />
                      </div>
                      {prev?.systolic && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[9px] text-slate-400 pointer-events-none truncate">
                          前:{prev.systolic}/{prev.diastolic}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-2">
                    <div className="relative pb-3">
                      <input
                        type="number"
                        inputMode="numeric"
                        placeholder="70"
                        className={`w-full text-center border rounded py-1.5 px-1 focus:ring-1 outline-none font-medium ${
                          isAbnormal('pulse', rowData.pulse || '') ? 'bg-red-50 border-red-300 text-red-600' : 'border-slate-300'
                        }`}
                        value={rowData.pulse || ''}
                        onChange={(e) => handleChange(res.id, 'pulse', e.target.value)}
                      />
                      {prev?.pulse && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[9px] text-slate-400 pointer-events-none truncate">
                          前:{prev.pulse}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-2">
                    <div className="relative pb-3">
                      <input
                        type="number"
                        inputMode="numeric"
                        placeholder="98"
                        className={`w-full text-center border rounded py-1.5 px-1 focus:ring-1 outline-none font-medium ${
                          isAbnormal('spo2', rowData.spo2 || '') ? 'bg-red-50 border-red-300 text-red-600 font-bold' : 'border-slate-300'
                        }`}
                        value={rowData.spo2 || ''}
                        onChange={(e) => handleChange(res.id, 'spo2', e.target.value)}
                      />
                      {prev?.spo2 && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[9px] text-slate-400 pointer-events-none truncate">
                          前:{prev.spo2}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-2">
                    <div className="flex gap-1 justify-center">
                      {['mealMorning', 'mealNoon', 'mealNight'].map((time) => {
                        const meal = (rowData[time as keyof VitalRecord] as Meal) || { main: 10, side: 10 };
                        return (
                          <div key={time} className="flex flex-col items-center gap-0.5 border border-slate-100 p-0.5 rounded bg-slate-50">
                            <span className="text-[8px] text-slate-400 font-bold">
                              {time === 'mealMorning' ? '朝' : time === 'mealNoon' ? '昼' : '晩'}
                            </span>
                            <div className="flex gap-0.5">
                              <input
                                type="number"
                                inputMode="numeric"
                                min="0"
                                max="10"
                                className="w-8 text-center text-[11px] border rounded p-0.5 font-medium"
                                value={meal.main}
                                onChange={(e) => handleMealChange(res.id, time as any, 'main', parseInt(e.target.value) || 0)}
                              />
                              <input
                                type="number"
                                inputMode="numeric"
                                min="0"
                                max="10"
                                className="w-8 text-center text-[11px] border border-blue-200 rounded p-0.5 bg-blue-50 font-medium"
                                value={meal.side}
                                onChange={(e) => handleMealChange(res.id, time as any, 'side', parseInt(e.target.value) || 0)}
                              />
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </td>
                  <td className="px-2 py-2">
                    <input
                      type="text"
                      inputMode="numeric"
                      placeholder="0"
                      className="w-full text-center border border-slate-300 rounded py-1.5 px-1 focus:ring-1 outline-none font-medium"
                      value={rowData.bowelCount || '0'}
                      onChange={(e) => handleChange(res.id, 'bowelCount', e.target.value)}
                    />
                  </td>
                  <td className="px-2 py-2">
                    <input
                      type="text"
                      placeholder="体調の変化や特記事項を入力..."
                      className="w-full border border-slate-300 rounded py-1.5 px-3 focus:ring-1 outline-none text-sm"
                      value={rowData.note || ''}
                      onChange={(e) => handleChange(res.id, 'note', e.target.value)}
                    />
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="flex justify-center pb-8 no-print">
         <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-start gap-3 max-w-2xl">
           <AlertCircle className="text-blue-500 mt-0.5 shrink-0" size={20} />
           <p className="text-xs text-blue-700 leading-relaxed">
             入力が完了したら右上の<b>「一括登録を実行」</b>ボタンを押してください。数値が見えにくい場合は、画面を横にスクロールしてご確認ください。
           </p>
         </div>
      </div>
    </div>
  );
};

