export default BatchInputTable;

import React, { useState, useMemo, useEffect } from 'react';
import { THRESHOLDS, DAYS_JP } from '../constants';
import { VitalRecord, Meal, Resident } from '../types';
import { Save, AlertCircle, Calendar } from 'lucide-react';

interface BatchInputTableProps {
  onSave: (records: VitalRecord[]) => void;
  residents: Resident[];
  records: VitalRecord[];
}

const BatchInputTable: React.FC<BatchInputTableProps> = ({ onSave, residents, records }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const [data, setData] = useState<Record<string, Partial<VitalRecord>>>(() => {
    const initial: Record<string, Partial<VitalRecord>> = {};
    residents.forEach(res => {
      initial[res.id] = {
        residentId: res.id,
        residentName: res.name,
        date: '',
        temperature: '',
        systolic: '',
        diastolic: '',
        pulse: '',
        spo2: '',
        mealMorning: { main: 10, side: 10 },
        mealNoon: { main: 10, side: 10 },
        mealNight: { main: 10, side: 10 },
        bowelCount: '0',
        note: ''
      };
    });
    return initial;
  });

  // Sync data state when residents list changes
  useEffect(() => {
    setData(prev => {
      const next = { ...prev };
      let changed = false;
      residents.forEach(res => {
        if (!next[res.id]) {
          next[res.id] = {
            residentId: res.id,
            residentName: res.name,
            temperature: '',
            systolic: '',
            diastolic: '',
            pulse: '',
            spo2: '',
            mealMorning: { main: 10, side: 10 },
            mealNoon: { main: 10, side: 10 },
            mealNight: { main: 10, side: 10 },
            bowelCount: '0',
            note: ''
          };
          changed = true;
        }
      });
      return changed ? next : prev;
    });
  }, [residents]);

  const formattedDateWithDay = useMemo(() => {
    const d = new Date(date);
    const day = DAYS_JP[d.getDay()];
    return `${date} (${day})`;
  }, [date]);

  // Map of last record per resident for reference
  const prevDataMap = useMemo(() => {
    const map: Record<string, VitalRecord> = {};
    const sorted = [...records].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    residents.forEach(res => {
      const last = sorted.find(r => r.residentId === res.id && r.date < date);
      if (last) map[res.id] = last;
    });
    return map;
  }, [records, date, residents]);

  const handleChange = (resId: string, field: keyof VitalRecord, value: any) => {
    setData(prev => ({
      ...prev,
      [resId]: { ...prev[resId], [field]: value }
    }));
  };

  const handleApplyPreviousBp = (resId: string) => {
    const prev = prevDataMap[resId];
    if (prev) {
      setData(prevData => ({
        ...prevData,
        [resId]: {
          ...prevData[resId],
          systolic: prev.systolic,
          diastolic: prev.diastolic
        }
      }));
    }
  };

  const handleBpFocus = (resId: string, e: React.FocusEvent<HTMLInputElement>) => {
    const prev = prevDataMap[resId];
    const current = data[resId];

    // 両方が空の場合にのみ前回の値を提案（デフォルトとして入力）
    if (prev && !current?.systolic && !current?.diastolic) {
      setData(prevData => ({
        ...prevData,
        [resId]: {
          ...prevData[resId],
          systolic: prev.systolic,
          diastolic: prev.diastolic
        }
      }));

      // 入力されたテキストを全選択状態にする（すぐに上書きできるように）
      setTimeout(() => e.target.select(), 0);
    }
  };

  const handleMealChange = (resId: string, time: 'mealMorning' | 'mealNoon' | 'mealNight', type: keyof Meal, value: number) => {
    setData(prev => {
      const row = prev[resId];
      if (!row) return prev;
      const currentMeal = (row[time] as Meal) || { main: 10, side: 10 };
      return {
        ...prev,
        [resId]: { 
          ...row, 
          [time]: { ...currentMeal, [type]: value }
        }
      };
    });
  };

  const handleSave = () => {
    const recordsToSave: VitalRecord[] = Object.values(data)
      .filter(d => d.residentId)
      .map(d => ({
        ...(d as any),
        date: date,
      } as VitalRecord));
    onSave(recordsToSave);
  };

  const isAbnormal = (field: string, value: string) => {
    const num = parseFloat(value);
    if (isNaN(num)) return false;
    if (field === 'temperature' && num >= THRESHOLDS.TEMP_HIGH) return true;
    if (field === 'systolic' && num >= THRESHOLDS.BP_SYSTOLIC_HIGH) return true;
    if (field === 'diastolic' && num >= THRESHOLDS.BP_DIASTOLIC_HIGH) return true;
    if (field === 'spo2' && num < THRESHOLDS.SPO2_LOW) return true;
    if (field === 'pulse' && (num >= THRESHOLDS.PULSE_HIGH || num <= THRESHOLDS.PULSE_LOW)) return true;
    return false;
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border">
