export default BatchInputTable;

import React, { useState, useMemo, useEffect } from 'react';
import { THRESHOLDS, DAYS_JP } from '../constants';
import { VitalRecord, Meal, Resident } from '../types';
import { Save, AlertCircle, Calendar } from 'lucide-react';

interface BatchInputTableProps {
  onSave: (records: VitalRecord[]) => void;
  residents: Resident[];
  records: VitalRecord[];
}

const BatchInputTable: React.FC<BatchInputTableProps> = ({ onSave, residents, records }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const [data, setData] = useState<Record<string, Partial<VitalRecord>>>(() => {
    const initial: Record<string, Partial<VitalRecord>> = {};
    residents.forEach(res => {
      initial[res.id] = {
        residentId: res.id,
        residentName: res.name,
        date: '',
        temperature: '',
        systolic: '',
        diastolic: '',
        pulse: '',
        spo2: '',
        mealMorning: { main: 10, side: 10 },
        mealNoon: { main: 10, side: 10 },
        mealNight: { main: 10, side: 10 },
        bowelCount: '0',
        note: ''
      };
    });
    return initial;
  });

  // Sync data state when residents list changes
  useEffect(() => {
    setData(prev => {
      const next = { ...prev };
      let changed = false;
      residents.forEach(res => {
        if (!next[res.id]) {
          next[res.id] = {
            residentId: res.id,
            residentName: res.name,
            temperature: '',
            systolic: '',
            diastolic: '',
            pulse: '',
            spo2: '',
            mealMorning: { main: 10, side: 10 },
            mealNoon: { main: 10, side: 10 },
            mealNight: { main: 10, side: 10 },
            bowelCount: '0',
            note: ''
          };
          changed = true;
        }
      });
      return changed ? next : prev;
    });
  }, [residents]);

  const formattedDateWithDay = useMemo(() => {
    const d = new Date(date);
    const day = DAYS_JP[d.getDay()];
    return `${date} (${day})`;
  }, [date]);

  // Map of last record per resident for reference
  const prevDataMap = useMemo(() => {
    const map: Record<string, VitalRecord> = {};
    const sorted = [...records].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    residents.forEach(res => {
      const last = sorted.find(r => r.residentId === res.id && r.date < date);
      if (last) map[res.id] = last;
    });
    return map;
  }, [records, date, residents]);

  const handleChange = (resId: string, field: keyof VitalRecord, value: any) => {
    setData(prev => ({
      ...prev,
      [resId]: { ...prev[resId], [field]: value }
    }));
  };

  const handleApplyPreviousBp = (resId: string) => {
    const prev = prevDataMap[resId];
    if (prev) {
      setData(prevData => ({
        ...prevData,
        [resId]: {
          ...prevData[resId],
          systolic: prev.systolic,
          diastolic: prev.diastolic
        }
      }));
    }
  };

  const handleBpFocus = (resId: string, e: React.FocusEvent<HTMLInputElement>) => {
    const prev = prevDataMap[resId];
    const current = data[resId];

    if (prev && !current?.systolic && !current?.diastolic) {
      setData(prevData => ({
        ...prevData,
        [resId]: {
          ...prevData[resId],
          systolic: prev.systolic,
          diastolic: prev.diastolic
        }
      }));
      setTimeout(() => e.target.select(), 0);
    }
  };

  const handleMealChange = (resId: string, time: 'mealMorning' | 'mealNoon' | 'mealNight', type: keyof Meal, value: number) => {
    setData(prev => {
      const row = prev[resId];
      if (!row) return prev;
      const currentMeal = (row[time] as Meal) || { main: 10, side: 10 };
      return {
        ...prev,
        [resId]: { 
          ...row, 
          [time]: { ...currentMeal, [type]: value }
        }
      };
    });
  };

  const handleSave = () => {
    const recordsToSave: VitalRecord[] = Object.values(data)
      .filter(d => d.residentId)
      .map(d => ({
        ...(d as any),
        date: date,
      } as VitalRecord));
    onSave(recordsToSave);
  };

  const isAbnormal = (field: string, value: string) => {
    const num = parseFloat(value);
    if (isNaN(num)) return false;
    if (field === 'temperature' && num >= THRESHOLDS.TEMP_HIGH) return true;
    if (field === 'systolic' && num >= THRESHOLDS.BP_SYSTOLIC_HIGH) return true;
    if (field === 'diastolic' && num >= THRESHOLDS.BP_DIASTOLIC_HIGH) return true;
    if (field === 'spo2' && num < THRESHOLDS.SPO2_LOW) return true;
    if (field === 'pulse' && (num >= THRESHOLDS.PULSE_HIGH || num <= THRESHOLDS.PULSE_LOW)) return true;
    return false;
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border">
        <div className="flex items-center gap-3">
          <Calendar className="text-blue-500" size={24} />
          <div>
            <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">記録日: {formattedDateWithDay}</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)}
              className="border rounded-md px-3 py-1.5 focus:ring-2 focus:ring-blue-500 outline-none text-slate-700 font-medium"
            />
          </div>
        </div>
        <button 
          onClick={handleSave}
          className="w-full sm:w-auto flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-lg font-semibold shadow-md transition-all active:scale-95"
        >
          <Save size={20} />
          一括登録を実行
        </button>
      </div>

      <div className="overflow-x-auto rounded-xl shadow-sm border border-slate-200 bg-white">
        <table className="min-w-max w-full divide-y divide-slate-200 text-sm">
          <thead className="bg-slate-50">
            <tr>
              <th className="px-4 py-3 text-left font-semibold text-slate-600 sticky left-0 bg-slate-50 z-10 w-48 border-r border-slate-200">氏名</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-32">体温</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-56">血圧 (上/下)</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-28">脈拍</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-28">SpO2</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-80">食事量 (朝/昼/晩)</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-28">排便</th>
              <th className="px-2 py-3 text-left font-semibold text-slate-600 min-w-[400px]">備考</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200">
            {residents.map((res) => {
              const prev = prevDataMap[res.id];
              const rowData = data[res.id];

              if (!rowData) return null;

              return (
                <tr key={res.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-4 py-3 font-medium text-slate-800 sticky left-0 bg-white z-10 border-r border-slate-200 shadow-[2px_0_5px_rgba(0,0,0,0.05)]">
                    <div className="flex flex-col">
                      <span className="text-[10px] text-slate-400 font-normal">#{res.roomNumber}</span>
                      <span className="truncate text-base">{res.name}</span>
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text"
                        inputMode="decimal"
                        placeholder="36.5"
                        className={`w-full text-center border rounded py-2 px-1 focus:ring-2 focus:ring-blue-500 outline-none font-bold text-base transition-all ${
                          isAbnormal('temperature', rowData.temperature || '') ? 'bg-red-50 border-red-400 text-red-600' : 'border-slate-300'
                        }`}
                        value={rowData.temperature || ''}
                        onChange={(e) => handleChange(res.id, 'temperature', e.target.value)}
                      />
                      {prev?.temperature && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[10px] text-slate-500 font-semibold pointer-events-none truncate bg-slate-100/50 rounded py-0.5">
                          前回: {prev.temperature}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5 group">
                      <div className="flex items-center gap-1">
                        <input
                          type="text"
                          inputMode="numeric"
                          placeholder="120"
                          className={`w-full text-center border rounded py-2 px-1 focus:ring-2 focus:ring-blue-500 outline-none font-bold text-base transition-all ${
                            isAbnormal('systolic', rowData.systolic || '') ? 'bg-red-50 border-red-400 text-red-600' : 'border-slate-300'
                          }`}
                          value={rowData.systolic || ''}
                          onChange={(e) => handleChange(res.id, 'systolic', e.target.value)}
                          onFocus={(e) => handleBpFocus(res.id, e)}
                        />
                        <span className="text-slate-400 font-bold">/</span>
                        <input
                          type="text"
                          inputMode="numeric"
                          placeholder="80"
                          className={`w-full text-center border rounded py-2 px-1 focus:ring-2 focus:ring-blue-500 outline-none font-bold text-base transition-all ${
                            isAbnormal('diastolic', rowData.diastolic || '') ? 'bg-red-50 border-red-400 text-red-600' : 'border-slate-300'
                          }`}
                          value={rowData.diastolic || ''}
                          onChange={(e) => handleChange(res.id, 'diastolic', e.target.value)}
                          onFocus={(e) => handleBpFocus(res.id, e)}
                        />
                      </div>
                      {prev?.systolic && (
                        <button
                          type="button"
                          onClick={() => handleApplyPreviousBp(res.id)}
                          className="absolute bottom-0 left-0 right-0 text-center text-[10px] text-blue-600 hover:text-blue-800 hover:underline transition-all font-bold truncate bg-blue-50 rounded py-0.5"
                          title="前回値を適用"
                        >
                          前回: {prev.systolic}/{prev.diastolic} 適用
                        </button>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text"
                        inputMode="numeric"
                        placeholder="70"
                        className={`w-full text-center border rounded py-2 px-1 focus:ring-2 focus:ring-blue-500 outline-none font-bold text-base transition-all ${
                          isAbnormal('pulse', rowData.pulse || '') ? 'bg-red-50 border-red-400 text-red-600' : 'border-slate-300'
                        }`}
                        value={rowData.pulse || ''}
                        onChange={(e) => handleChange(res.id, 'pulse', e.target.value)}
                      />
                      {prev?.pulse && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[10px] text-slate-500 font-semibold pointer-events-none truncate bg-slate-100/50 rounded py-0.5">
                          前回: {prev.pulse}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text"
                        inputMode="numeric"
                        placeholder="98"
                        className={`w-full text-center border rounded py-2 px-1 focus:ring-2 focus:ring-blue-500 outline-none font-bold text-base transition-all ${
                          isAbnormal('spo2', rowData.spo2 || '') ? 'bg-red-50 border-red-400 text-red-600' : 'border-slate-300'
                        }`}
                        value={rowData.spo2 || ''}
                        onChange={(e) => handleChange(res.id, 'spo2', e.target.value)}
                      />
                      {prev?.spo2 && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[10px] text-slate-500 font-semibold pointer-events-none truncate bg-slate-100/50 rounded py-0.5">
                          前回: {prev.spo2}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="flex gap-2 justify-center">
                      {['mealMorning', 'mealNoon', 'mealNight'].map((time) => {
                        const meal = (rowData[time as keyof VitalRecord] as Meal) || { main: 10, side: 10 };
                        return (
                          <div key={time} className="flex flex-col items-center gap-1 border border-slate-200 p-1.5 rounded bg-slate-50">
                            <span className="text-[10px] text-slate-600 font-bold">
                              {time === 'mealMorning' ? '朝' : time === 'mealNoon' ? '昼' : '晩'}
                            </span>
                            <div className="flex gap-1">
                              <div className="flex flex-col items-center">
                                <span className="text-[8px] text-slate-400 scale-90">主</span>
                                <input
                                  type="text"
                                  inputMode="numeric"
                                  className="w-10 text-center text-xs border rounded p-1 font-bold focus:ring-1 focus:ring-blue-400 outline-none"
                                  value={meal.main}
                                  onChange={(e) => handleMealChange(res.id, time as any, 'main', parseInt(e.target.value) || 0)}
                                />
                              </div>
                              <div className="flex flex-col items-center">
                                <span className="text-[8px] text-slate-400 scale-90">副</span>
                                <input
                                  type="text"
                                  inputMode="numeric"
                                  className="w-10 text-center text-xs border border-blue-200 rounded p-1 bg-blue-50 font-bold focus:ring-1 focus:ring-blue-400 outline-none"
                                  value={meal.side}
                                  onChange={(e) => handleMealChange(res.id, time as any, 'side', parseInt(e.target.value) || 0)}
                                />
                              </div>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text"
                        inputMode="numeric"
                        placeholder="0"
                        className="w-full text-center border border-slate-300 rounded py-2 px-1 focus:ring-2 focus:ring-blue-500 outline-none font-bold text-base transition-all"
                        value={rowData.bowelCount || '0'}
                        onChange={(e) => handleChange(res.id, 'bowelCount', e.target.value)}
                      />
                      {prev?.bowelCount !== undefined && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[10px] text-slate-500 font-semibold pointer-events-none truncate bg-slate-100/50 rounded py-0.5">
                          前回: {prev.bowelCount}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <input
                      type="text"
                      placeholder="体調の変化や特記事項を入力..."
                      className="w-full border border-slate-300 rounded py-2 px-4 focus:ring-2 focus:ring-blue-500 outline-none text-sm transition-all"
                      value={rowData.note || ''}
                      onChange={(e) => handleChange(res.id, 'note', e.target.value)}
                    />
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="flex justify-center pb-8 no-print">
         <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-start gap-3 max-w-2xl">
           <AlertCircle className="text-blue-500 mt-0.5 shrink-0" size={20} />
           <p className="text-xs text-blue-700 leading-relaxed">
             <b>【モバイル対応】</b> 数字入力欄では自動的に数字キーボードが表示されます。
             <br />
             <b>【前回値リファレンス】</b> 入力欄の下に表示されている「前回値」を参考にしてください。血圧欄はタップで前回値をそのまま適用できます。
           </p>
         </div>
      </div>
    </div>
  );
};

