import React, { useState, useMemo } from 'react';
import { THRESHOLDS } from '../constants';
import { VitalRecord, Resident } from '../types';
import { User, Printer, FileText, TrendingUp, Calendar } from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';

interface IndividualHistoryProps {
  records: VitalRecord[];
  residents: Resident[];
  facilityName: string;
}

const IndividualHistory: React.FC<IndividualHistoryProps> = ({ records, residents, facilityName }) => {
  const [selectedId, setSelectedId] = useState(residents[0]?.id || '');

  // デフォルトの期間を当月の1日から末日に設定
  const defaultDates = useMemo(() => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  }, []);

  const [startDate, setStartDate] = useState(defaultDates.firstDay);
  const [endDate, setEndDate] = useState(defaultDates.lastDay);

  const filteredRecords = useMemo(() => {
    return records
      .filter(r => r.residentId === selectedId && r.date >= startDate && r.date <= endDate)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [records, selectedId, startDate, endDate]);

  const resident = useMemo(() => 
    residents.find(r => r.id === selectedId) || residents[0], 
    [selectedId, residents]
  );

  const chartData = useMemo(() => {
    return filteredRecords
      .filter(r => !r.isAbsent)
      .map(r => ({
        date: r.date.split('-').slice(1).join('/'),
        temp: parseFloat(r.temperature) || null,
        systolic: parseInt(r.systolic) || null,
        diastolic: parseInt(r.diastolic) || null,
        pulse: parseInt(r.pulse) || null,
      }));
  }, [filteredRecords]);

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border no-print">
        <div className="flex flex-col md:flex-row items-start md:items-center gap-4 w-full xl:w-auto">
          <div className="flex items-center gap-3 w-full md:w-64">
            <div className="bg-slate-100 p-2 rounded-lg shrink-0">
              <User className="text-slate-500" />
