          <div className="flex items-center gap-2 w-full md:w-auto">
            <div className="bg-slate-100 p-2 rounded-lg shrink-0">
              <Calendar className="text-slate-500" />
            </div>
            <div className="flex items-center gap-2">
              <div className="flex-1">
                <label className="block text-xs font-semibold text-slate-500 mb-1">開始日</label>
                <input 
                  type="date"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                  className="border rounded-md px-3 py-1.5 focus:ring-2 focus:ring-blue-500 outline-none font-medium text-sm"
                />
