              <span className="mt-4 text-slate-400">～</span>
              <div className="flex-1">
                <label className="block text-xs font-semibold text-slate-500 mb-1">終了日</label>
                <input 
                  type="date"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                  className="border rounded-md px-3 py-1.5 focus:ring-2 focus:ring-blue-500 outline-none font-medium text-sm"
                />
              </div>
            </div>
