        <div className="flex gap-2 w-full xl:w-auto">
          <button 
            onClick={handlePrint}
            className="flex-1 xl:flex-none flex items-center justify-center gap-2 bg-slate-800 hover:bg-slate-900 text-white px-6 py-2.5 rounded-lg text-sm font-semibold transition-all shadow-md active:scale-95"
          >
            <Printer size={18} />
            印刷 / PDF出力
          </button>
        </div>
      </div>

      {filteredRecords.some(r => !r.isAbsent) && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 no-print">
          <div className="bg-white p-6 rounded-xl shadow-sm border">
            <h3 className="text-sm font-bold mb-4 flex items-center gap-2">
              <TrendingUp size={16} className="text-blue-500" />
              血圧・脈拍推移
            </h3>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <XAxis dataKey="date" fontSize={10} />
                  <YAxis fontSize={10} domain={['dataMin - 10', 'dataMax + 10']} />
                  <Tooltip />
                  <Legend iconType="circle" wrapperStyle={{ fontSize: '10px' }} />
                  <Line type="monotone" dataKey="systolic" stroke="#ef4444" name="血圧(上)" strokeWidth={2} dot={{ r: 3 }} />
                  <Line type="monotone" dataKey="diastolic" stroke="#3b82f6" name="血圧(下)" strokeWidth={2} dot={{ r: 3 }} />
                  <Line type="monotone" dataKey="pulse" stroke="#10b981" name="脈拍" strokeWidth={1} strokeDasharray="5 5" dot={{ r: 2 }} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border">
            <h3 className="text-sm font-bold mb-4 flex items-center gap-2">
              <TrendingUp size={16} className="text-orange-500" />
              体温推移
            </h3>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <XAxis dataKey="date" fontSize={10} />
                  <YAxis fontSize={10} domain={[35, 38]} />
                  <Tooltip />
                  <Legend iconType="circle" wrapperStyle={{ fontSize: '10px' }} />
                  <Line type="monotone" dataKey="temp" stroke="#f59e0b" name="体温(℃)" strokeWidth={3} dot={{ r: 4 }} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white p-8 rounded-xl shadow-sm border min-h-[800px]">
        <div className="border-b-2 border-slate-900 pb-4 mb-6 flex justify-between items-end">
          <div>
            <h2 className="text-3xl font-bold text-slate-900 tracking-tight">月間バイタル管理表</h2>
            <p className="text-slate-500 mt-1 font-medium">施設名: {facilityName}</p>
          </div>
          <div className="text-right">
            <p className="text-xl font-bold text-slate-800">氏名: {resident?.name} 様</p>
            <p className="text-sm text-slate-500 font-medium">居室: {resident?.roomNumber}号室</p>
            <p className="text-[10px] text-slate-400 mt-1">期間: {startDate} ～ {endDate}</p>
          </div>
        </div>

        {filteredRecords.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-slate-400">
            <FileText size={64} className="mb-4 opacity-20" />
            <p>指定された期間の記録データがありません。</p>
          </div>
        ) : (
          <table className="w-full border-collapse border border-slate-300 text-sm">
            <thead>
              <tr className="bg-slate-50">
                <th className="border border-slate-300 px-2 py-2 w-28">日付</th>
                <th className="border border-slate-300 px-2 py-2">体温</th>
                <th className="border border-slate-300 px-2 py-2">血圧 (上/下)</th>
                <th className="border border-slate-300 px-2 py-2">脈拍</th>
                <th className="border border-slate-300 px-2 py-2">SpO2</th>
                <th className="border border-slate-300 px-2 py-2 text-xs">食事(朝/昼/晩)</th>
                <th className="border border-slate-300 px-2 py-2">排便</th>
                <th className="border border-slate-300 px-2 py-2">備考</th>
              </tr>
            </thead>
            <tbody>
              {[...filteredRecords].reverse().map((rec, i) => (
                <tr key={i} className={`text-center ${rec.isAbsent ? 'bg-slate-50 text-slate-400 italic' : ''}`}>
                  <td className="border border-slate-300 px-2 py-2 font-medium">{rec.date}</td>
                  {rec.isAbsent ? (
                    <td colSpan={7} className="border border-slate-300 px-2 py-2 text-left">
                      利用無し / 欠食
                      {rec.note && <span className="ml-4">({rec.note})</span>}
                    </td>
                  ) : (
                    <>
                      <td className={`border border-slate-300 px-2 py-2 ${parseFloat(rec.temperature) >= THRESHOLDS.TEMP_HIGH ? 'text-red-600 font-bold bg-red-50' : ''}`}>
                        {rec.temperature}
                      </td>
                      <td className={`border border-slate-300 px-2 py-2 ${parseFloat(rec.systolic) >= THRESHOLDS.BP_SYSTOLIC_HIGH ? 'text-red-600 font-bold bg-red-50' : ''}`}>
                        {rec.systolic} / {rec.diastolic}
                      </td>
                      <td className={`border border-slate-300 px-2 py-2 ${(parseInt(rec.pulse) >= THRESHOLDS.PULSE_HIGH || parseInt(rec.pulse) <= THRESHOLDS.PULSE_LOW) ? 'text-red-600 font-bold bg-red-50' : ''}`}>
                        {rec.pulse}
                      </td>
                      <td className={`border border-slate-300 px-2 py-2 ${parseFloat(rec.spo2) < THRESHOLDS.SPO2_LOW ? 'text-red-600 font-bold bg-red-50' : ''}`}>
                        {rec.spo2}%
                      </td>
                      <td className="border border-slate-300 px-1 py-1">
                        <div className="flex flex-col text-[10px] items-center">
                          <span>朝 {rec.mealMorning.main}/{rec.mealMorning.side}</span>
                          <span>昼 {rec.mealNoon.main}/{rec.mealNoon.side}</span>
                          <span>晩 {rec.mealNight.main}/{rec.mealNight.side}</span>
                        </div>
                      </td>
                      <td className="border border-slate-300 px-2 py-2">{rec.bowelCount}</td>
                      <td className="border border-slate-300 px-2 py-2 text-left text-xs max-w-xs overflow-hidden text-ellipsis whitespace-nowrap">
                        {rec.note}
                      </td>
                    </>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        )}

        <div className="mt-8 text-xs text-slate-400 print-only">
          <p>作成日: {new Date().toLocaleDateString('ja-JP')} | 出力元: VitalSign Pro システム</p>
        </div>
      </div>
    </div>
  );
};

export default IndividualHistory;

import React, { useState, useMemo, useEffect } from 'react';
import { THRESHOLDS, ERR_LIMITS, DAYS_JP } from '../constants';
import { VitalRecord, Meal, Resident } from '../types';
import { Save, AlertCircle, Calendar, UserX } from 'lucide-react';

interface BatchInputTableProps {
  onSave: (records: VitalRecord[]) => void;
  residents: Resident[];
  records: VitalRecord[];
}

const BatchInputTable: React.FC<BatchInputTableProps> = ({ onSave, residents, records }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const [data, setData] = useState<Record<string, Partial<VitalRecord>>>(() => {
    const initial: Record<string, Partial<VitalRecord>> = {};
    residents.forEach(res => {
      initial[res.id] = {
        residentId: res.id,
        residentName: res.name,
        date: '',
        temperature: '',
        systolic: '',
        diastolic: '',
        pulse: '',
        spo2: '',
        mealMorning: { main: 10, side: 10 },
        mealNoon: { main: 10, side: 10 },
        mealNight: { main: 10, side: 10 },
        bowelCount: '0',
        note: '',
        isAbsent: false
      };
    });
    return initial;
  });

  useEffect(() => {
    setData(prev => {
      const next = { ...prev };
      let changed = false;
      residents.forEach(res => {
        if (!next[res.id]) {
          next[res.id] = {
            residentId: res.id,
            residentName: res.name,
            temperature: '',
            systolic: '',
            diastolic: '',
            pulse: '',
            spo2: '',
            mealMorning: { main: 10, side: 10 },
            mealNoon: { main: 10, side: 10 },
            mealNight: { main: 10, side: 10 },
            bowelCount: '0',
            note: '',
            isAbsent: false
          };
          changed = true;
        }
      });
      return changed ? next : prev;
    });
  }, [residents]);

  const formattedDateWithDay = useMemo(() => {
    const d = new Date(date);
    const day = DAYS_JP[d.getDay()];
    return `${date} (${day})`;
  }, [date]);

  const prevDataMap = useMemo(() => {
    const map: Record<string, VitalRecord> = {};
    const sorted = [...records].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    residents.forEach(res => {
      const last = sorted.find(r => r.residentId === res.id && r.date < date);
      if (last) map[res.id] = last;
    });
    return map;
  }, [records, date, residents]);

  const handleChange = (resId: string, field: keyof VitalRecord, value: any) => {
    setData(prev => ({
      ...prev,
      [resId]: { ...prev[resId], [field]: value }
    }));
  };

  const handleMealChange = (resId: string, time: 'mealMorning' | 'mealNoon' | 'mealNight', type: keyof Meal, value: number) => {
    setData(prev => {
      const row = prev[resId];
      if (!row) return prev;
      const currentMeal = (row[time] as Meal) || { main: 10, side: 10 };
      return {
        ...prev,
        [resId]: { 
          ...row, 
          [time]: { ...currentMeal, [type]: value }
        }
      };
    });
  };

  const isInvalidInput = (field: string, value: string) => {
    const num = parseFloat(value);
    if (isNaN(num)) return false;
    if (field === 'temperature' && (num < ERR_LIMITS.TEMP_MIN || num > ERR_LIMITS.TEMP_MAX)) return true;
    if (field === 'systolic' && (num < ERR_LIMITS.BP_SYS_MIN || num > ERR_LIMITS.BP_SYS_MAX)) return true;
    if (field === 'diastolic' && (num < ERR_LIMITS.BP_DIA_MIN || num > ERR_LIMITS.BP_DIA_MAX)) return true;
    if (field === 'spo2' && (num < ERR_LIMITS.SPO2_MIN || num > 100)) return true;
    if (field === 'pulse' && (num < ERR_LIMITS.PULSE_MIN || num > ERR_LIMITS.PULSE_MAX)) return true;
    return false;
  };

  const isAbnormal = (field: string, value: string) => {
    const num = parseFloat(value);
    if (isNaN(num)) return false;
    if (field === 'temperature' && num >= THRESHOLDS.TEMP_HIGH) return true;
    if (field === 'systolic' && num >= THRESHOLDS.BP_SYSTOLIC_HIGH) return true;
    // Fix: Correct property name to BP_DIASTOLIC_HIGH
    if (field === 'diastolic' && num >= THRESHOLDS.BP_DIASTOLIC_HIGH) return true; // Fix label typo in prev version if any
    if (field === 'spo2' && num < THRESHOLDS.SPO2_LOW) return true;
    if (field === 'pulse' && (num >= THRESHOLDS.PULSE_HIGH || num <= THRESHOLDS.PULSE_LOW)) return true;
    return false;
  };

  const handleSave = () => {
    const missingRecords: string[] = [];
    const invalidRecords: string[] = [];
    const recordsToSave: VitalRecord[] = [];

    residents.forEach(res => {
      const row = data[res.id];
      if (!row) return;

      if (row.isAbsent) {
        recordsToSave.push({ ...(row as any), date: date, residentName: res.name });
        return;
      }

      // 入力忘れチェック (主要項目がすべて空)
      const isPartiallyFilled = row.temperature || row.systolic || row.diastolic || row.pulse || row.spo2;
      if (!isPartiallyFilled) {
        missingRecords.push(res.name);
      }

      // 入力ミスチェック
      if (
        isInvalidInput('temperature', row.temperature || '') ||
        isInvalidInput('systolic', row.systolic || '') ||
        isInvalidInput('diastolic', row.diastolic || '') ||
        isInvalidInput('pulse', row.pulse || '') ||
        isInvalidInput('spo2', row.spo2 || '')
      ) {
        invalidRecords.push(res.name);
      }

      recordsToSave.push({ ...(row as any), date: date, residentName: res.name });
    });

    if (invalidRecords.length > 0) {
      alert(`以下の利用者の入力値に明らかな誤りがあります。赤枠の箇所を確認してください：\n${invalidRecords.join(', ')}`);
      return;
    }

    if (missingRecords.length > 0) {
      if (!window.confirm(`以下の利用者のバイタルが未入力です。利用無しの場合は「利用無し」にチェックを入れてください。このまま保存しますか？\n${missingRecords.join(', ')}`)) {
        return;
      }
    }

    onSave(recordsToSave);
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border">
        <div className="flex items-center gap-3">
          <Calendar className="text-blue-500" size={24} />
          <div>
            <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">記録日: {formattedDateWithDay}</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)}
              className="border rounded-md px-3 py-1.5 focus:ring-2 focus:ring-blue-500 outline-none text-slate-700 font-medium"
            />
          </div>
        </div>
        <button 
          onClick={handleSave}
          className="w-full sm:w-auto flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-lg font-semibold shadow-md transition-all active:scale-95"
        >
          <Save size={20} />
          一括登録を実行
        </button>
      </div>

      <div className="overflow-x-auto rounded-xl shadow-sm border border-slate-200 bg-white">
        <table className="min-w-max w-full divide-y divide-slate-200 text-sm">
          <thead className="bg-slate-50">
            <tr>
              <th className="px-4 py-3 text-left font-semibold text-slate-600 sticky left-0 bg-slate-50 z-10 w-48 border-r border-slate-200">氏名</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-24">利用無し</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-32">体温</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-56">血圧 (上/下)</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-28">脈拍</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-28">SpO2</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-80">食事量 (朝/昼/晩)</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-28">排便</th>
              <th className="px-2 py-3 text-left font-semibold text-slate-600 min-w-[400px]">備考</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200">
            {residents.map((res) => {
              const prev = prevDataMap[res.id];
              const rowData = data[res.id];
              if (!rowData) return null;

              const isAbsent = rowData.isAbsent;

              return (
                <tr key={res.id} className={`hover:bg-slate-50 transition-colors ${isAbsent ? 'bg-slate-100 opacity-60' : ''}`}>
                  <td className="px-4 py-3 font-medium text-slate-800 sticky left-0 bg-inherit z-10 border-r border-slate-200 shadow-[2px_0_5px_rgba(0,0,0,0.05)]">
                    <div className="flex flex-col">
                      <span className="text-[10px] text-slate-400 font-normal">#{res.roomNumber}</span>
                      <span className="truncate text-base">{res.name}</span>
                    </div>
                  </td>
                  <td className="px-2 py-3 text-center">
                    <button 
                      onClick={() => handleChange(res.id, 'isAbsent', !isAbsent)}
                      className={`p-2 rounded-full transition-colors ${isAbsent ? 'bg-slate-700 text-white' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}
                      title="利用無しに設定"
                    >
                      <UserX size={18} />
                    </button>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text"
                        inputMode="decimal"
                        disabled={isAbsent}
                        placeholder="36.5"
                        className={`w-full text-center border rounded py-2 px-1 focus:ring-2 focus:ring-blue-500 outline-none font-bold text-base transition-all ${
                          isInvalidInput('temperature', rowData.temperature || '') ? 'bg-red-200 border-red-600' :
                          isAbnormal('temperature', rowData.temperature || '') ? 'bg-red-50 border-red-400 text-red-600' : 'border-slate-300'
                        }`}
                        value={rowData.temperature || ''}
                        onChange={(e) => handleChange(res.id, 'temperature', e.target.value)}
                      />
                      {prev?.temperature && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[10px] text-slate-400 font-medium pointer-events-none truncate bg-slate-100/30 rounded py-0.5">
                          前回: {prev.temperature}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5 group">
                      <div className="flex items-center gap-1">
                        <input
                          type="text"
                          inputMode="numeric"
                          disabled={isAbsent}
                          placeholder="120"
                          className={`w-full text-center border rounded py-2 px-1 focus:ring-2 focus:ring-blue-500 outline-none font-bold text-base transition-all ${
                            isInvalidInput('systolic', rowData.systolic || '') ? 'bg-red-200 border-red-600' :
                            isAbnormal('systolic', rowData.systolic || '') ? 'bg-red-50 border-red-400 text-red-600' : 'border-slate-300'
                          }`}
                          value={rowData.systolic || ''}
                          onChange={(e) => handleChange(res.id, 'systolic', e.target.value)}
                        />
                        <span className="text-slate-400 font-bold">/</span>
                        <input
                          type="text"
                          inputMode="numeric"
                          disabled={isAbsent}
                          placeholder="80"
                          className={`w-full text-center border rounded py-2 px-1 focus:ring-2 focus:ring-blue-500 outline-none font-bold text-base transition-all ${
                            isInvalidInput('diastolic', rowData.diastolic || '') ? 'bg-red-200 border-red-600' :
                            isAbnormal('diastolic', rowData.diastolic || '') ? 'bg-red-50 border-red-400 text-red-600' : 'border-slate-300'
                          }`}
                          value={rowData.diastolic || ''}
                          onChange={(e) => handleChange(res.id, 'diastolic', e.target.value)}
                        />
                      </div>
                      {prev?.systolic && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[10px] text-slate-400 font-medium pointer-events-none truncate bg-slate-100/30 rounded py-0.5">
                          前回: {prev.systolic}/{prev.diastolic}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text"
                        inputMode="numeric"
                        disabled={isAbsent}
                        placeholder="70"
                        className={`w-full text-center border rounded py-2 px-1 focus:ring-2 focus:ring-blue-500 outline-none font-bold text-base transition-all ${
                          isInvalidInput('pulse', rowData.pulse || '') ? 'bg-red-200 border-red-600' :
                          isAbnormal('pulse', rowData.pulse || '') ? 'bg-red-50 border-red-400 text-red-600' : 'border-slate-300'
                        }`}
                        value={rowData.pulse || ''}
                        onChange={(e) => handleChange(res.id, 'pulse', e.target.value)}
                      />
                      {prev?.pulse && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[10px] text-slate-400 font-medium pointer-events-none truncate bg-slate-100/30 rounded py-0.5">
                          前回: {prev.pulse}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text"
                        inputMode="numeric"
                        disabled={isAbsent}
                        placeholder="98"
                        className={`w-full text-center border rounded py-2 px-1 focus:ring-2 focus:ring-blue-500 outline-none font-bold text-base transition-all ${
                          isInvalidInput('spo2', rowData.spo2 || '') ? 'bg-red-200 border-red-600' :
                          isAbnormal('spo2', rowData.spo2 || '') ? 'bg-red-50 border-red-400 text-red-600' : 'border-slate-300'
                        }`}
                        value={rowData.spo2 || ''}
                        onChange={(e) => handleChange(res.id, 'spo2', e.target.value)}
                      />
                      {prev?.spo2 && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[10px] text-slate-400 font-medium pointer-events-none truncate bg-slate-100/30 rounded py-0.5">
                          前回: {prev.spo2}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="flex gap-2 justify-center">
                      {['mealMorning', 'mealNoon', 'mealNight'].map((time) => {
                        const meal = (rowData[time as keyof VitalRecord] as Meal) || { main: 10, side: 10 };
                        return (
                          <div key={time} className="flex flex-col items-center gap-1 border border-slate-200 p-1.5 rounded bg-slate-50">
                            <span className="text-[10px] text-slate-600 font-bold">
                              {time === 'mealMorning' ? '朝' : time === 'mealNoon' ? '昼' : '晩'}
                            </span>
                            <div className="flex gap-1">
                              <div className="flex flex-col items-center">
                                <span className="text-[8px] text-slate-400 scale-90">主</span>
                                <input
                                  type="text"
                                  inputMode="numeric"
                                  disabled={isAbsent}
                                  className="w-10 text-center text-xs border rounded p-1 font-bold focus:ring-1 focus:ring-blue-400 outline-none"
                                  value={meal.main}
                                  onChange={(e) => handleMealChange(res.id, time as any, 'main', parseInt(e.target.value) || 0)}
                                />
                              </div>
                              <div className="flex flex-col items-center">
                                <span className="text-[8px] text-slate-400 scale-90">副</span>
                                <input
                                  type="text"
                                  inputMode="numeric"
                                  disabled={isAbsent}
                                  className="w-10 text-center text-xs border border-blue-200 rounded p-1 bg-blue-50 font-bold focus:ring-1 focus:ring-blue-400 outline-none"
                                  value={meal.side}
                                  onChange={(e) => handleMealChange(res.id, time as any, 'side', parseInt(e.target.value) || 0)}
                                />
                              </div>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text"
                        inputMode="numeric"
                        disabled={isAbsent}
                        placeholder="0"
                        className="w-full text-center border border-slate-300 rounded py-2 px-1 focus:ring-2 focus:ring-blue-500 outline-none font-bold text-base transition-all"
                        value={rowData.bowelCount || '0'}
                        onChange={(e) => handleChange(res.id, 'bowelCount', e.target.value)}
                      />
                      {prev?.bowelCount !== undefined && (
                        <span className="absolute bottom-0 left-0 right-0 text-center text-[10px] text-slate-400 font-medium pointer-events-none truncate bg-slate-100/30 rounded py-0.5">
                          前回: {prev.bowelCount}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <input
                      type="text"
                      disabled={isAbsent}
                      placeholder="体調の変化や特記事項を入力..."
                      className="w-full border border-slate-300 rounded py-2 px-4 focus:ring-2 focus:ring-blue-500 outline-none text-sm transition-all"
                      value={rowData.note || ''}
                      onChange={(e) => handleChange(res.id, 'note', e.target.value)}
                    />
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="flex justify-center pb-8 no-print">
         <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-start gap-3 max-w-2xl">
           <AlertCircle className="text-blue-500 mt-0.5 shrink-0" size={20} />
           <p className="text-xs text-blue-700 leading-relaxed">
             <b>【入力バリデーション】</b> 明らかな入力ミス（濃い赤枠）がある場合は保存できません。発熱等の要注意項目は薄い赤背景で表示されます。
             <br />
             <b>【入力忘れ防止】</b> 利用者の利用がない場合は、左側の <b>利用無しボタン</b> を押してください。チェックがない状態で空欄のまま保存しようとすると確認メッセージが表示されます。
           </p>
         </div>
      </div>
    </div>
  );
};

