/**
 * 明らかな入力ミス（物理的限界）の判定
 */
export const ERR_LIMITS = {
  TEMP_MIN: 33.0,
  TEMP_MAX: 43.0,
  BP_SYS_MIN: 40,
  BP_SYS_MAX: 280,
  BP_DIA_MIN: 30,
  BP_DIA_MAX: 180,
  PULSE_MIN: 30,
  PULSE_MAX: 220,
  SPO2_MIN: 50
};

