import React, { useState, useMemo, useEffect } from 'react';
import { THRESHOLDS, ERR_LIMITS, DAYS_JP } from '../constants';
import { VitalRecord, Meal, Resident } from '../types';
import { Save, AlertCircle, Calendar, UserX } from 'lucide-react';

interface BatchInputTableProps {
  onSave: (records: VitalRecord[]) => void;
  residents: Resident[];
  records: VitalRecord[];
}

const BatchInputTable: React.FC<BatchInputTableProps> = ({ onSave, residents, records }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const [data, setData] = useState<Record<string, Partial<VitalRecord>>>(() => {
    const initial: Record<string, Partial<VitalRecord>> = {};
    residents.forEach(res => {
      initial[res.id] = {
        residentId: res.id,
        residentName: res.name,
        date: '',
        temperature: '',
        systolic: '',
        diastolic: '',
        pulse: '',
        spo2: '',
        mealMorning: { main: 10, side: 10 },
        mealNoon: { main: 10, side: 10 },
        mealNight: { main: 10, side: 10 },
        bowelCount: '0',
        note: '',
        isAbsent: false
      };
    });
    return initial;
  });

  useEffect(() => {
    setData(prev => {
      const next = { ...prev };
      let changed = false;
      residents.forEach(res => {
        if (!next[res.id]) {
          next[res.id] = {
            residentId: res.id,
            residentName: res.name,
            temperature: '', systolic: '', diastolic: '', pulse: '', spo2: '',
            mealMorning: { main: 10, side: 10 },
            mealNoon: { main: 10, side: 10 },
            mealNight: { main: 10, side: 10 },
            bowelCount: '0', note: '', isAbsent: false
          };
          changed = true;
        }
      });
      return changed ? next : prev;
    });
  }, [residents]);

  const prevDataMap = useMemo(() => {
    const map: Record<string, VitalRecord> = {};
    const sorted = [...records].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    residents.forEach(res => {
      const last = sorted.find(r => r.residentId === res.id && r.date < date);
      if (last) map[res.id] = last;
    });
    return map;
  }, [records, date, residents]);

  const handleChange = (resId: string, field: keyof VitalRecord, value: any) => {
    setData(prev => ({ ...prev, [resId]: { ...prev[resId], [field]: value } }));
  };

  const handleMealChange = (resId: string, time: 'mealMorning' | 'mealNoon' | 'mealNight', type: keyof Meal, value: number) => {
    setData(prev => {
      const row = prev[resId];
      if (!row) return prev;
      const currentMeal = (row[time] as Meal) || { main: 10, side: 10 };
      return { ...prev, [resId]: { ...row, [time]: { ...currentMeal, [type]: value } } };
    });
  };

  // 明らかな入力ミスの判定（赤枠・保存不可）
  const isInputError = (field: string, value: string) => {
    const num = parseFloat(value);
    if (isNaN(num)) return false;
    if (field === 'temperature' && (num < ERR_LIMITS.TEMP_MIN || num > ERR_LIMITS.TEMP_MAX)) return true;
    if (field === 'systolic' && (num < ERR_LIMITS.BP_SYS_MIN || num > ERR_LIMITS.BP_SYS_MAX)) return true;
    if (field === 'diastolic' && (num < ERR_LIMITS.BP_DIA_MIN || num > ERR_LIMITS.BP_DIA_MAX)) return true;
    if (field === 'pulse' && (num < ERR_LIMITS.PULSE_MIN || num > ERR_LIMITS.PULSE_MAX)) return true;
    if (field === 'spo2' && (num < ERR_LIMITS.SPO2_MIN || num > 100)) return true;
    return false;
  };

  // アンダーソン・土肥の基準に基づくスタイル判定
  const getStatusClass = (field: string, value: string) => {
    const num = parseFloat(value);
    if (isNaN(num)) return 'border-slate-300';
    if (isInputError(field, value)) return 'bg-red-200 border-red-600 animate-pulse'; // 重大な入力ミス

    if (field === 'temperature') {
      if (num >= THRESHOLDS.STOP.TEMP) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.TEMP) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'systolic') {
      if (num >= THRESHOLDS.STOP.BP_SYS) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.BP_SYS) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'diastolic') {
      if (num >= THRESHOLDS.STOP.BP_DIA) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.BP_DIA) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'pulse') {
      if (num >= THRESHOLDS.STOP.PULSE_HIGH || num <= THRESHOLDS.STOP.PULSE_LOW) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.PULSE_HIGH || num <= THRESHOLDS.CAUTION.PULSE_LOW) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'spo2') {
      if (num < THRESHOLDS.STOP.SPO2) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num < THRESHOLDS.CAUTION.SPO2) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    return 'border-slate-300';
  };

  const handleSave = () => {
    const toSave: VitalRecord[] = [];
    const missing: string[] = [];
    const errors: string[] = [];

    residents.forEach(res => {
      const row = data[res.id];
      if (!row) return;

      if (row.isAbsent) {
        toSave.push({ ...(row as any), date, residentName: res.name });
        return;
      }

      // 入力エラーの有無
      const hasError = ['temperature', 'systolic', 'diastolic', 'pulse', 'spo2'].some(f => isInputError(f, (row as any)[f]));
      if (hasError) errors.push(res.name);

      // 入力漏れの有無（数値が一つも入っていない）
      const isEmpty = !row.temperature && !row.systolic && !row.diastolic && !row.pulse && !row.spo2;
      if (isEmpty) missing.push(res.name);

      toSave.push({ ...(row as any), date, residentName: res.name });
    });

    if (errors.length > 0) {
      alert(`以下の利用者の入力値に明らかな誤りがあります。赤色の点滅箇所を確認してください：\n${errors.join(', ')}`);
      return;
    }

    if (missing.length > 0) {
      const msg = `以下の利用者のバイタルが未入力です。利用無しの場合は「利用無し」に設定してください。このまま保存しますか？\n${missing.join(', ')}`;
      if (!window.confirm(msg)) return;
    }

    onSave(toSave);
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border">
        <div className="flex items-center gap-3">
          <Calendar className="text-blue-500" size={24} />
          <div>
            <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">記録日</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)}
              className="border rounded-md px-3 py-1.5 focus:ring-2 focus:ring-blue-500 outline-none text-slate-700 font-medium"
            />
          </div>
        </div>
        <button 
          onClick={handleSave}
          className="w-full sm:w-auto flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-lg font-semibold shadow-md transition-all active:scale-95"
        >
          <Save size={20} />
          一括登録を実行
        </button>
      </div>

      <div className="overflow-x-auto rounded-xl shadow-sm border border-slate-200 bg-white">
        <table className="min-w-max w-full divide-y divide-slate-200 text-sm">
          <thead className="bg-slate-50">
            <tr>
              <th className="px-4 py-3 text-left font-semibold text-slate-600 sticky left-0 bg-slate-50 z-10 border-r w-48">氏名</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-24">利用無し</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-28">体温</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-48">血圧 (上/下)</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-24">脈拍</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-24">SpO2</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-64">食事 (朝/昼/晩)</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-20">排便</th>
              <th className="px-2 py-3 text-left font-semibold text-slate-600 min-w-[300px]">備考</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200">
            {residents.map((res) => {
              const row = data[res.id] || {};
              const prev = prevDataMap[res.id];
              return (
                <tr key={res.id} className={`hover:bg-slate-50 transition-colors ${row.isAbsent ? 'bg-slate-100 opacity-60' : ''}`}>
                  <td className="px-4 py-3 font-medium text-slate-800 sticky left-0 bg-inherit z-10 border-r shadow-[2px_0_5px_rgba(0,0,0,0.05)]">
                    <div className="flex flex-col">
                      <span className="text-[10px] text-slate-400 font-normal">#{res.roomNumber}</span>
                      <span className="truncate text-base">{res.name}</span>
                    </div>
                  </td>
                  <td className="px-2 py-3 text-center">
                    <button 
                      onClick={() => handleChange(res.id, 'isAbsent', !row.isAbsent)}
                      className={`p-1.5 rounded-full transition-colors ${row.isAbsent ? 'bg-slate-700 text-white' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}
                    >
                      <UserX size={18} />
                    </button>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text" inputMode="decimal" disabled={row.isAbsent}
                        className={`w-full text-center border rounded py-1.5 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all ${getStatusClass('temperature', row.temperature || '')}`}
                        value={row.temperature || ''}
                        onChange={(e) => handleChange(res.id, 'temperature', e.target.value)}
                      />
                      <span className="absolute bottom-0 left-0 right-0 text-[10px] text-center text-slate-400 truncate">前回:{prev?.temperature || '-'}</span>
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <div className="flex items-center gap-1">
                        <input
                          type="text" inputMode="numeric" disabled={row.isAbsent}
                          className={`w-full text-center border rounded py-1.5 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all ${getStatusClass('systolic', row.systolic || '')}`}
                          value={row.systolic || ''}
                          onChange={(e) => handleChange(res.id, 'systolic', e.target.value)}
                        />
                        <span className="text-slate-400">/</span>
                        <input
                          type="text" inputMode="numeric" disabled={row.isAbsent}
                          className={`w-full text-center border rounded py-1.5 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all ${getStatusClass('diastolic', row.diastolic || '')}`}
                          value={row.diastolic || ''}
                          onChange={(e) => handleChange(res.id, 'diastolic', e.target.value)}
                        />
                      </div>
                      <span className="absolute bottom-0 left-0 right-0 text-[10px] text-center text-slate-400 truncate">前回:{prev ? `${prev.systolic}/${prev.diastolic}` : '-'}</span>
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text" inputMode="numeric" disabled={row.isAbsent}
                        className={`w-full text-center border rounded py-1.5 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all ${getStatusClass('pulse', row.pulse || '')}`}
                        value={row.pulse || ''}
                        onChange={(e) => handleChange(res.id, 'pulse', e.target.value)}
                      />
                      <span className="absolute bottom-0 left-0 right-0 text-[10px] text-center text-slate-400 truncate">前回:{prev?.pulse || '-'}</span>
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text" inputMode="numeric" disabled={row.isAbsent}
                        className={`w-full text-center border rounded py-1.5 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all ${getStatusClass('spo2', row.spo2 || '')}`}
                        value={row.spo2 || ''}
                        onChange={(e) => handleChange(res.id, 'spo2', e.target.value)}
                      />
                      <span className="absolute bottom-0 left-0 right-0 text-[10px] text-center text-slate-400 truncate">前回:{prev?.spo2 || '-'}</span>
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="flex gap-1 justify-center">
                      {['mealMorning', 'mealNoon', 'mealNight'].map((time) => {
                        const meal = (row[time as keyof VitalRecord] as Meal) || { main: 10, side: 10 };
                        return (
                          <div key={time} className="flex flex-col items-center gap-0.5 border p-1 rounded bg-slate-50 text-[10px]">
                            <span className="font-bold">{time === 'mealMorning' ? '朝' : time === 'mealNoon' ? '昼' : '晩'}</span>
                            <div className="flex gap-0.5">
                              <input type="text" inputMode="numeric" disabled={row.isAbsent} className="w-6 text-center border rounded py-0.5 font-bold" value={meal.main} onChange={(e) => handleMealChange(res.id, time as any, 'main', parseInt(e.target.value) || 0)} />
                              <input type="text" inputMode="numeric" disabled={row.isAbsent} className="w-6 text-center border border-blue-200 bg-blue-50 rounded py-0.5 font-bold" value={meal.side} onChange={(e) => handleMealChange(res.id, time as any, 'side', parseInt(e.target.value) || 0)} />
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <input type="text" inputMode="numeric" disabled={row.isAbsent} className="w-full text-center border rounded py-1.5 font-bold" value={row.bowelCount || '0'} onChange={(e) => handleChange(res.id, 'bowelCount', e.target.value)} />
                  </td>
                  <td className="px-2 py-3">
                    <input type="text" disabled={row.isAbsent} className="w-full border rounded py-1.5 px-2 text-xs focus:ring-2 focus:ring-blue-500 outline-none" value={row.note || ''} onChange={(e) => handleChange(res.id, 'note', e.target.value)} placeholder="..." />
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 flex gap-3 no-print">
        <AlertCircle className="text-blue-500 shrink-0" />
        <div className="text-xs text-blue-700 space-y-1">
          <p><b>アンダーソン・土肥の基準:</b> 38.0℃以上、血圧160/100以上、脈拍120以上/50以下はリハ中止（赤色表示）</p>
          <p><b>入力忘れ:</b> 全てのバイタルが空の利用者がいる場合警告が出ます。お休みの場合は<b>左のアイコン</b>をタップして「利用無し」にしてください。</p>
        </div>
      </div>
    </div>
  );
};

