import React, { useState, useMemo } from 'react';
import { THRESHOLDS } from '../constants';
import { VitalRecord, Resident } from '../types';
import { User, Printer, FileText, TrendingUp, Calendar } from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';

interface IndividualHistoryProps {
  records: VitalRecord[];
  residents: Resident[];
  facilityName: string;
}

const IndividualHistory: React.FC<IndividualHistoryProps> = ({ records, residents, facilityName }) => {
  const [selectedId, setSelectedId] = useState(residents[0]?.id || '');

  // 期間指定の初期値（当月の1日から末日まで）
  const defaultRange = useMemo(() => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  }, []);

  const [startDate, setStartDate] = useState(defaultRange.firstDay);
  const [endDate, setEndDate] = useState(defaultRange.lastDay);

  const filteredRecords = useMemo(() => {
    return records
      .filter(r => r.residentId === selectedId && r.date >= startDate && r.date <= endDate)
