import React, { useState, useEffect } from 'react';
import { AppView, VitalRecord, Resident } from './types';
import BatchInputTable from './components/BatchInputTable';
import IndividualHistory from './components/IndividualHistory';
import Dashboard from './components/Dashboard';
import ResidentMaster from './components/ResidentMaster';
import { LayoutGrid, Users, ClipboardList, Info, Settings } from 'lucide-react';
import { INITIAL_RESIDENTS } from './constants';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.BATCH_INPUT);
  const [records, setRecords] = useState<VitalRecord[]>([]);
  const [residents, setResidents] = useState<Resident[]>(INITIAL_RESIDENTS);
  const [facilityName, setFacilityName] = useState<string>('陽光ケアホーム');

  useEffect(() => {
    const savedRecords = localStorage.getItem('vital_records');
    if (savedRecords) {
      setRecords(JSON.parse(savedRecords));
    }

    const savedResidents = localStorage.getItem('residents_master');
    if (savedResidents) {
      setResidents(JSON.parse(savedResidents));
    }

    const savedFacility = localStorage.getItem('facility_name');
    if (savedFacility) {
      setFacilityName(savedFacility);
    }
  }, []);

  /**
   * レコードを保存または更新する（日付と利用者IDが一致すれば上書き）
   */
  const saveBatchRecords = (newRecords: VitalRecord[]) => {
    setRecords(prev => {
      const next = [...prev];
      newRecords.forEach(nr => {
        const idx = next.findIndex(r => r.residentId === nr.residentId && r.date === nr.date);
        if (idx > -1) {
          next[idx] = nr; // 既存データを更新（上書き）
        } else {
          next.push(nr); // 新規データを追加
        }
      });
      localStorage.setItem('vital_records', JSON.stringify(next));
      return next;
    });
  };

  const updateResidents = (newResidents: Resident[]) => {
    setResidents(newResidents);
    localStorage.setItem('residents_master', JSON.stringify(newResidents));
  };

  const updateFacilityName = (name: string) => {
    setFacilityName(name);
    localStorage.setItem('facility_name', name);
  };

  return (
    <div className="min-h-screen flex flex-col">
      <header className="bg-white border-b sticky top-0 z-50 no-print">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-2">
              <div className="bg-blue-600 p-2 rounded-lg">
                <ClipboardList className="text-white w-6 h-6" />
              </div>
              <h1 className="text-xl font-bold text-slate-800 tracking-tight">VitalSign Pro</h1>
            </div>
            <nav className="flex space-x-1 sm:space-x-4">
              <button
                onClick={() => setCurrentView(AppView.BATCH_INPUT)}
                className={`flex items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  currentView === AppView.BATCH_INPUT ? 'bg-blue-50 text-blue-700' : 'text-slate-500 hover:bg-slate-50'
                }`}
              >
                <LayoutGrid size={18} />
                <span className="hidden sm:inline">一括入力</span>
              </button>
              <button
                onClick={() => setCurrentView(AppView.INDIVIDUAL_HISTORY)}
                className={`flex items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  currentView === AppView.INDIVIDUAL_HISTORY ? 'bg-blue-50 text-blue-700' : 'text-slate-500 hover:bg-slate-50'
                }`}
              >
                <Users size={18} />
                <span className="hidden sm:inline">個人履歴</span>
              </button>
              <button
                onClick={() => setCurrentView(AppView.DASHBOARD)}
                className={`flex items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  currentView === AppView.DASHBOARD ? 'bg-blue-50 text-blue-700' : 'text-slate-500 hover:bg-slate-50'
                }`}
              >
                <Info size={18} />
                <span className="hidden sm:inline">概要</span>
              </button>
              <button
                onClick={() => setCurrentView(AppView.RESIDENT_MASTER)}
                className={`flex items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  currentView === AppView.RESIDENT_MASTER ? 'bg-blue-50 text-blue-700' : 'text-slate-500 hover:bg-slate-50'
                }`}
              >
                <Settings size={18} />
                <span className="hidden sm:inline">マスタ</span>
              </button>
            </nav>
          </div>
        </div>
      </header>

      <main className="flex-1 overflow-auto p-4 sm:p-6 lg:p-8">
        <div className="max-w-7xl mx-auto h-full">
          {currentView === AppView.BATCH_INPUT && (
            <BatchInputTable onSave={saveBatchRecords} residents={residents} records={records} />
          )}
          {currentView === AppView.INDIVIDUAL_HISTORY && (
            <IndividualHistory records={records} residents={residents} facilityName={facilityName} />
          )}
          {currentView === AppView.DASHBOARD && (
            <Dashboard records={records} />
          )}
          {currentView === AppView.RESIDENT_MASTER && (
            <ResidentMaster 
              residents={residents} 
              onUpdate={updateResidents} 
              facilityName={facilityName}
              onFacilityNameUpdate={updateFacilityName}
            />
          )}
        </div>
      </main>

      <footer className="bg-white border-t py-4 text-center text-xs text-slate-400 no-print">
        &copy; 2024 VitalSign Pro - 介護現場効率化システム
      </footer>
    </div>
  );
};

