      if (num >= THRESHOLDS.CAUTION.BP_DIA) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'pulse') {
      if (num >= THRESHOLDS.STOP.PULSE_HIGH || num <= THRESHOLDS.STOP.PULSE_LOW) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.PULSE_HIGH || num <= THRESHOLDS.CAUTION.PULSE_LOW) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'spo2') {
      if (num < THRESHOLDS.STOP.SPO2) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num < THRESHOLDS.CAUTION.SPO2) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    return 'border-slate-300';
  };

  return (
