import React, { useState, useEffect } from 'react';
import { Resident } from '../types';
import { Plus, Trash2, Save, UserCheck, Building, RotateCcw, UserMinus } from 'lucide-react';
import { INITIAL_RESIDENTS } from '../constants';

interface ResidentMasterProps {
  residents: Resident[];
  onUpdate: (residents: Resident[]) => void;
  facilityName: string;
  onFacilityNameUpdate: (name: string) => void;
}

const ResidentMaster: React.FC<ResidentMasterProps> = ({ 
  residents, 
  onUpdate, 
  facilityName, 
  onFacilityNameUpdate 
}) => {
  // ローカルステートで編集内容を保持
  const [localResidents, setLocalResidents] = useState<Resident[]>(residents);
  const [localFacilityName, setLocalFacilityName] = useState<string>(facilityName);
  const [isDirty, setIsDirty] = useState(false);

  // 親（App.tsx）のデータが更新された場合に同期
  useEffect(() => {
    setLocalResidents(residents);
    setIsDirty(false);
  }, [residents]);

  useEffect(() => {
    setLocalFacilityName(facilityName);
  }, [facilityName]);

  const handleUpdate = (id: string, field: keyof Resident, value: string) => {
    setLocalResidents(prev => prev.map(r => r.id === id ? { ...r, [field]: value } : r));
    setIsDirty(true);
  };

  const handleAdd = () => {
    const newId = `res-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    const newResident: Resident = { 
      id: newId, 
      name: '', 
      roomNumber: '' 
    };
    setLocalResidents(prev => [...prev, newResident]);
    setIsDirty(true);
  };

  const handleRemove = (id: string) => {
    if (window.confirm('この利用者をリストから削除しますか？\n（「設定を保存」を押すまで確定されません）')) {
      setLocalResidents(prev => prev.filter(r => r.id !== id));
      setIsDirty(true);
    }
  };

  const handleClearAll = () => {
    if (window.confirm('すべての利用者を削除しますか？\n（この操作は「設定を保存」を押すまで確定されません）')) {
      setLocalResidents([]);
      setIsDirty(true);
    }
  };

  const handleResetToDefault = () => {
    if (window.confirm('利用者リストを初期状態（30名のサンプル）に戻しますか？\n（この操作は「設定を保存」を押すまで確定されません）')) {
      setLocalResidents(INITIAL_RESIDENTS);
      setIsDirty(true);
    }
  };

  const handleSave = () => {
    // 空の名前のチェック（任意で許可するが警告を出す）
    const hasEmptyName = localResidents.some(r => !r.name.trim());
    if (hasEmptyName && localResidents.length > 0) {
      if (!window.confirm('名前が空の利用者が含まれています。そのまま保存しますか？')) {
        return;
      }
    }

    onUpdate(localResidents);
    onFacilityNameUpdate(localFacilityName);
    setIsDirty(false);
    alert('マスタ設定を保存しました。');
  };

  return (
    <div className="space-y-6">
      {/* System Settings Section */}
      <div className="bg-white p-6 rounded-xl border shadow-sm">
        <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2 mb-4">
          <Building size={20} className="text-blue-600" />
          施設基本設定
        </h2>
        <div className="max-w-md">
          <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">施設名称</label>
          <input 
            type="text" 
            value={localFacilityName}
            onChange={(e) => {
              setLocalFacilityName(e.target.value);
              setIsDirty(true);
            }}
            placeholder="施設名を入力してください"
            className="w-full border rounded-md px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none font-medium"
          />
        </div>
      </div>

      {/* Resident Master Section */}
      <div className="bg-white p-6 rounded-xl border shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-800">利用者マスタ設定</h2>
          <p className="text-sm text-slate-500">入所者の氏名と居室番号を管理します。（現在: {localResidents.length}名）</p>
        </div>
        <div className="flex flex-wrap gap-2 w-full md:w-auto">
          <button 
            type="button"
            onClick={handleAdd}
            className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2.5 rounded-lg font-semibold transition-all active:scale-95"
          >
            <Plus size={18} />
            新規追加
          </button>
          <button 
            type="button"
            onClick={handleSave}
            className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-2.5 rounded-lg font-semibold transition-all shadow-md active:scale-95 ${
              isDirty ? 'bg-blue-600 hover:bg-blue-700 text-white animate-pulse' : 'bg-slate-200 text-slate-500 cursor-not-allowed'
            }`}
            disabled={!isDirty}
          >
            <Save size={18} />
            設定を保存
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl border shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider w-32">居室番号</th>
                <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">氏名</th>
                <th className="px-6 py-3 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider w-24">操作</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-slate-200">
              {localResidents.map((res) => (
                <tr key={res.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-3 whitespace-nowrap">
                    <input 
                      type="text" 
                      value={res.roomNumber}
                      placeholder="例: 101"
                      onChange={(e) => handleUpdate(res.id, 'roomNumber', e.target.value)}
                      className="w-full border border-slate-200 rounded px-2 py-1.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                    />
                  </td>
                  <td className="px-6 py-3 whitespace-nowrap">
                    <input 
                      type="text" 
                      value={res.name}
                      placeholder="氏名を入力"
                      onChange={(e) => handleUpdate(res.id, 'name', e.target.value)}
                      className="w-full border border-slate-200 rounded px-2 py-1.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                    />
                  </td>
                  <td className="px-6 py-3 whitespace-nowrap text-right">
                    <button 
                      type="button"
                      onClick={() => handleRemove(res.id)}
                      title="削除"
                      className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-all"
                    >
                      <Trash2 size={18} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {localResidents.length === 0 && (
          <div className="py-20 text-center text-slate-400">
             <UserCheck size={48} className="mx-auto mb-4 opacity-20" />
             <p>利用者が登録されていません。</p>
             <button onClick={handleAdd} className="mt-4 text-blue-600 hover:underline text-sm font-bold">最初の利用者を追加する</button>
          </div>
        )}
      </div>

      <div className="flex flex-col sm:flex-row gap-3 pt-4 border-t border-slate-200 no-print">
        <button 
          type="button"
          onClick={handleResetToDefault}
          className="flex items-center justify-center gap-2 text-xs text-slate-500 hover:text-slate-800 bg-slate-100 hover:bg-slate-200 px-4 py-2 rounded-lg transition-all"
        >
          <RotateCcw size={14} />
          初期状態に戻す
        </button>
        <button 
          type="button"
          onClick={handleClearAll}
          className="flex items-center justify-center gap-2 text-xs text-red-500 hover:text-red-700 bg-red-50 hover:bg-red-100 px-4 py-2 rounded-lg transition-all"
        >
          <UserMinus size={14} />
          全員削除
        </button>
      </div>

      <div className="bg-amber-50 border border-amber-200 p-4 rounded-lg">
        <p className="text-xs text-amber-800 leading-relaxed font-medium">
          ※ 利用者の追加・削除・編集を行った後は、必ず右上の<b>「設定を保存」</b>ボタンを押してください。保存せずに他の画面（一括入力など）へ切り替えると変更内容は破棄されます。
        </p>
      </div>
    </div>
  );
};

export default ResidentMaster;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { THRESHOLDS, ERR_LIMITS } from '../constants';
import { VitalRecord, Meal, Resident } from '../types';
import { AlertCircle, Calendar, UserX, CheckCircle2, CloudUpload, Loader2 } from 'lucide-react';

interface BatchInputTableProps {
  onSave: (records: VitalRecord[]) => void;
  residents: Resident[];
  records: VitalRecord[];
}

const BatchInputTable: React.FC<BatchInputTableProps> = ({ onSave, residents, records }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [isSaving, setIsSaving] = useState(false);

  // フォームデータの初期状態を生成
  const createInitialRow = useCallback((res: Resident): Partial<VitalRecord> => ({
    residentId: res.id,
    residentName: res.name,
    temperature: '',
    systolic: '',
    diastolic: '',
    pulse: '',
    spo2: '',
    mealMorning: { main: 10, side: 10 },
    mealNoon: { main: 10, side: 10 },
    mealNight: { main: 10, side: 10 },
    bowelCount: '0',
    note: '',
    isAbsent: false
  }), []);

  const [data, setData] = useState<Record<string, Partial<VitalRecord>>>({});

  // 日付または全体レコードが変更された際、その日の既存データをロードする
  useEffect(() => {
    const nextData: Record<string, Partial<VitalRecord>> = {};
    residents.forEach(res => {
      const existing = records.find(r => r.residentId === res.id && r.date === date);
      if (existing) {
        nextData[res.id] = { ...existing };
      } else {
        nextData[res.id] = createInitialRow(res);
      }
    });
    setData(nextData);
  }, [date, residents, records, createInitialRow]);

  // 直近の記録（比較用）
  const prevDataMap = useMemo(() => {
    const map: Record<string, VitalRecord> = {};
    const sorted = [...records].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    residents.forEach(res => {
      const last = sorted.find(r => r.residentId === res.id && r.date < date);
      if (last) map[res.id] = last;
    });
    return map;
  }, [records, date, residents]);

  /**
   * 指定した利用者のデータを即座に親へ保存依頼する
   */
  const triggerAutoSave = (resId: string, updatedRow?: Partial<VitalRecord>) => {
    const row = updatedRow || data[resId];
    if (!row) return;

    // 数値の異常チェック（バリデーション失敗時は保存しない）
    const hasError = ['temperature', 'systolic', 'diastolic', 'pulse', 'spo2'].some(f => 
      isInputError(f, (row as any)[f])
    );
    if (hasError) return;

    setIsSaving(true);
    // レコードとして不完全な状態でも、日付を付与して保存
    onSave([{ ...row, date } as VitalRecord]);

    // 擬似的な保存中表示
    setTimeout(() => setIsSaving(false), 800);
  };

  const handleChange = (resId: string, field: keyof VitalRecord, value: any, autoSave = false) => {
    let finalValue = value;

    // 体温の小数点自動挿入ロジック
    if (field === 'temperature' && typeof value === 'string') {
      const digits = value.replace(/[^\d]/g, '');
      if (digits.length === 3 && !value.includes('.')) {
        // 3桁の数字のみの場合、2桁目の後にドットを挿入（例: 365 -> 36.5）
        finalValue = `${digits.slice(0, 2)}.${digits.slice(2)}`;
      }
    }

    setData(prev => {
      const newRow = { ...prev[resId], [field]: finalValue };
      const next = { ...prev, [resId]: newRow };
      if (autoSave) triggerAutoSave(resId, next[resId]);
      return next;
    });
  };

  const handleMealChange = (resId: string, time: 'mealMorning' | 'mealNoon' | 'mealNight', type: keyof Meal, value: number) => {
    const row = data[resId];
    if (!row) return;
    const currentMeal = (row[time] as Meal) || { main: 10, side: 10 };
    const newMeal = { ...currentMeal, [type]: value };
    const newRow = { ...row, [time]: newMeal };

    setData(prev => ({ ...prev, [resId]: newRow }));
    triggerAutoSave(resId, newRow);
  };

  const isInputError = (field: string, value: string) => {
    const num = parseFloat(value);
    if (!value || isNaN(num)) return false;
    if (field === 'temperature' && (num < ERR_LIMITS.TEMP_MIN || num > ERR_LIMITS.TEMP_MAX)) return true;
    if (field === 'systolic' && (num < ERR_LIMITS.BP_SYS_MIN || num > ERR_LIMITS.BP_SYS_MAX)) return true;
    if (field === 'diastolic' && (num < ERR_LIMITS.BP_DIA_MIN || num > ERR_LIMITS.BP_DIA_MAX)) return true;
    if (field === 'pulse' && (num < ERR_LIMITS.PULSE_MIN || num > ERR_LIMITS.PULSE_MAX)) return true;
    if (field === 'spo2' && (num < ERR_LIMITS.SPO2_MIN || num > 100)) return true;
    return false;
  };

  const getStatusClass = (field: string, value: string) => {
    const num = parseFloat(value);
    if (isNaN(num)) return 'border-slate-300';
    if (isInputError(field, value)) return 'bg-red-200 border-red-600 animate-pulse';

    if (field === 'temperature') {
      if (num >= THRESHOLDS.STOP.TEMP) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.TEMP) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'systolic') {
      if (num >= THRESHOLDS.STOP.BP_SYS) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.BP_SYS) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'diastolic') {
      if (num >= THRESHOLDS.STOP.BP_DIA) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.BP_DIA) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'pulse') {
      if (num >= THRESHOLDS.STOP.PULSE_HIGH || num <= THRESHOLDS.STOP.PULSE_LOW) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.PULSE_HIGH || num <= THRESHOLDS.CAUTION.PULSE_LOW) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'spo2') {
      if (num < THRESHOLDS.STOP.SPO2) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num < THRESHOLDS.CAUTION.SPO2) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    return 'border-slate-300';
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border">
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-3">
            <Calendar className="text-blue-500" size={24} />
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-0.5">記録日を選択</label>
              <input 
                type="date" 
                value={date} 
                onChange={(e) => setDate(e.target.value)}
                className="border rounded-md px-3 py-1 text-slate-700 font-bold focus:ring-2 focus:ring-blue-500 outline-none"
              />
            </div>
          </div>

          <div className="h-10 w-[1px] bg-slate-200 hidden sm:block"></div>

          <div className="flex items-center gap-2">
            {isSaving ? (
              <div className="flex items-center gap-2 text-blue-600 font-semibold text-sm animate-pulse">
                <Loader2 size={18} className="animate-spin" />
                <span>保存中...</span>
              </div>
            ) : (
              <div className="flex items-center gap-2 text-emerald-600 font-semibold text-sm">
                <CheckCircle2 size={18} />
                <span>すべての変更を保存済み</span>
              </div>
            )}
          </div>
        </div>

        <div className="hidden lg:flex items-center gap-2 text-xs text-slate-400 bg-slate-50 px-3 py-1.5 rounded-full border">
          <CloudUpload size={14} />
          <span>入力すると自動的にデータベースへ同期されます</span>
        </div>
      </div>

      <div className="overflow-x-auto rounded-xl shadow-sm border border-slate-200 bg-white">
        <table className="min-w-max w-full divide-y divide-slate-200 text-sm">
