import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { THRESHOLDS, ERR_LIMITS } from '../constants';
import { VitalRecord, Meal, Resident } from '../types';
import { AlertCircle, Calendar, UserX, CheckCircle2, CloudUpload, Loader2 } from 'lucide-react';

interface BatchInputTableProps {
  onSave: (records: VitalRecord[]) => void;
  residents: Resident[];
  records: VitalRecord[];
}

const BatchInputTable: React.FC<BatchInputTableProps> = ({ onSave, residents, records }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [isSaving, setIsSaving] = useState(false);

  // フォームデータの初期状態を生成
  const createInitialRow = useCallback((res: Resident): Partial<VitalRecord> => ({
    residentId: res.id,
    residentName: res.name,
    temperature: '',
    systolic: '',
    diastolic: '',
    pulse: '',
    spo2: '',
    mealMorning: { main: 10, side: 10 },
    mealNoon: { main: 10, side: 10 },
    mealNight: { main: 10, side: 10 },
    bowelCount: '0',
    note: '',
    isAbsent: false
  }), []);

  const [data, setData] = useState<Record<string, Partial<VitalRecord>>>({});

  // 日付または全体レコードが変更された際、その日の既存データをロードする
  useEffect(() => {
    const nextData: Record<string, Partial<VitalRecord>> = {};
    residents.forEach(res => {
      const existing = records.find(r => r.residentId === res.id && r.date === date);
      if (existing) {
        nextData[res.id] = { ...existing };
      } else {
        nextData[res.id] = createInitialRow(res);
      }
    });
    setData(nextData);
  }, [date, residents, records, createInitialRow]);

  // 直近の記録（比較用）
  const prevDataMap = useMemo(() => {
    const map: Record<string, VitalRecord> = {};
    const sorted = [...records].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    residents.forEach(res => {
      const last = sorted.find(r => r.residentId === res.id && r.date < date);
      if (last) map[res.id] = last;
    });
    return map;
  }, [records, date, residents]);

  /**
   * 指定した利用者のデータを即座に親へ保存依頼する
   */
  const triggerAutoSave = (resId: string, updatedRow?: Partial<VitalRecord>) => {
    const row = updatedRow || data[resId];
    if (!row) return;

    // 数値の異常チェック（バリデーション失敗時は保存しない）
    const hasError = ['temperature', 'systolic', 'diastolic', 'pulse', 'spo2'].some(f => 
      isInputError(f, (row as any)[f])
    );
    if (hasError) return;

    setIsSaving(true);
    onSave([{ ...row, date } as VitalRecord]);

    setTimeout(() => setIsSaving(false), 800);
  };

  const handleChange = (resId: string, field: keyof VitalRecord, value: any, autoSave = false) => {
    let finalValue = value;

    // 体温の小数点自動挿入ロジック (例: 365 -> 36.5)
    if (field === 'temperature' && typeof value === 'string') {
      const digits = value.replace(/[^\d]/g, '');
      if (digits.length === 3 && !value.includes('.')) {
        finalValue = `${digits.slice(0, 2)}.${digits.slice(2)}`;
      }
    }

    setData(prev => {
      const newRow = { ...prev[resId], [field]: finalValue };
      const next = { ...prev, [resId]: newRow };
      if (autoSave) triggerAutoSave(resId, next[resId]);
      return next;
    });
  };

  const handleMealChange = (resId: string, time: 'mealMorning' | 'mealNoon' | 'mealNight', type: keyof Meal, value: number) => {
    const row = data[resId];
    if (!row) return;
    const currentMeal = (row[time] as Meal) || { main: 10, side: 10 };
    const newMeal = { ...currentMeal, [type]: value };
    const newRow = { ...row, [time]: newMeal };

    setData(prev => ({ ...prev, [resId]: newRow }));
    triggerAutoSave(resId, newRow);
  };

  const isInputError = (field: string, value: string) => {
    const num = parseFloat(value);
    if (!value || isNaN(num)) return false;
    if (field === 'temperature' && (num < ERR_LIMITS.TEMP_MIN || num > ERR_LIMITS.TEMP_MAX)) return true;
    if (field === 'systolic' && (num < ERR_LIMITS.BP_SYS_MIN || num > ERR_LIMITS.BP_SYS_MAX)) return true;
    if (field === 'diastolic' && (num < ERR_LIMITS.BP_DIA_MIN || num > ERR_LIMITS.BP_DIA_MAX)) return true;
    if (field === 'pulse' && (num < ERR_LIMITS.PULSE_MIN || num > ERR_LIMITS.PULSE_MAX)) return true;
    if (field === 'spo2' && (num < ERR_LIMITS.SPO2_MIN || num > 100)) return true;
    return false;
  };

  const getStatusClass = (field: string, value: string) => {
    const num = parseFloat(value);
    if (isNaN(num)) return 'border-slate-300';
    if (isInputError(field, value)) return 'bg-red-200 border-red-600 animate-pulse';

    if (field === 'temperature') {
      if (num >= THRESHOLDS.STOP.TEMP) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.TEMP) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'systolic') {
      if (num >= THRESHOLDS.STOP.BP_SYS || num <= THRESHOLDS.STOP.BP_SYS_LOW) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.BP_SYS || num <= THRESHOLDS.CAUTION.BP_SYS_LOW) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'diastolic') {
      if (num >= THRESHOLDS.STOP.BP_DIA || num <= THRESHOLDS.STOP.BP_DIA_LOW) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.BP_DIA || num <= THRESHOLDS.CAUTION.BP_DIA_LOW) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'pulse') {
      if (num >= THRESHOLDS.STOP.PULSE_HIGH || num <= THRESHOLDS.STOP.PULSE_LOW) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num >= THRESHOLDS.CAUTION.PULSE_HIGH || num <= THRESHOLDS.CAUTION.PULSE_LOW) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    if (field === 'spo2') {
      if (num < THRESHOLDS.STOP.SPO2) return 'bg-red-50 border-red-400 text-red-600 font-bold';
      if (num < THRESHOLDS.CAUTION.SPO2) return 'bg-amber-50 border-amber-400 text-amber-600 font-bold';
    }
    return 'border-slate-300';
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border no-print">
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-3">
            <Calendar className="text-blue-500" size={24} />
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-0.5">記録日を選択</label>
              <input 
                type="date" 
                value={date} 
                onChange={(e) => setDate(e.target.value)}
                className="border rounded-md px-3 py-1 text-slate-700 font-bold focus:ring-2 focus:ring-blue-500 outline-none"
              />
            </div>
          </div>

          <div className="h-10 w-[1px] bg-slate-200 hidden sm:block"></div>

          <div className="flex items-center gap-2">
            {isSaving ? (
              <div className="flex items-center gap-2 text-blue-600 font-semibold text-sm animate-pulse">
                <Loader2 size={18} className="animate-spin" />
                <span>保存中...</span>
              </div>
            ) : (
              <div className="flex items-center gap-2 text-emerald-600 font-semibold text-sm">
                <CheckCircle2 size={18} />
                <span>すべての変更を保存済み</span>
              </div>
            )}
          </div>
        </div>

        <div className="hidden lg:flex items-center gap-2 text-xs text-slate-400 bg-slate-50 px-3 py-1.5 rounded-full border">
          <CloudUpload size={14} />
          <span>入力すると自動的にデータベースへ同期されます</span>
        </div>
      </div>

      <div className="overflow-x-auto rounded-xl shadow-sm border border-slate-200 bg-white">
        <table className="min-w-max w-full divide-y divide-slate-200 text-sm">
          <thead className="bg-slate-50">
            <tr>
              <th className="px-4 py-3 text-left font-semibold text-slate-600 sticky left-0 bg-slate-50 z-30 border-r shadow-[2px_0_0px_rgba(0,0,0,0.05)] w-48">氏名</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-24">利用無し</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-28">体温</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-48">血圧 (上/下)</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-24">脈拍</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-24">SpO2</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-64">食事 (朝/昼/晩)</th>
              <th className="px-2 py-3 text-center font-semibold text-slate-600 w-20">排便</th>
              <th className="px-2 py-3 text-left font-semibold text-slate-600 min-w-[300px]">備考</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200">
            {residents.map((res) => {
              const row = data[res.id] || {};
              const prev = prevDataMap[res.id];
              return (
                <tr key={res.id} className={`group hover:bg-slate-50 transition-colors ${row.isAbsent ? 'bg-slate-100 opacity-60' : ''}`}>
                  <td className={`px-4 py-3 font-medium text-slate-800 sticky left-0 z-20 border-r shadow-[2px_0_5px_rgba(0,0,0,0.05)] ${
                    row.isAbsent ? 'bg-slate-100' : 'bg-white group-hover:bg-slate-50'
                  }`}>
                    <div className="flex flex-col">
                      <span className="text-[10px] text-slate-400 font-normal">#{res.roomNumber}</span>
                      <span className="truncate text-base">{res.name}</span>
                    </div>
                  </td>
                  <td className="px-2 py-3 text-center">
                    <button 
                      onClick={() => handleChange(res.id, 'isAbsent', !row.isAbsent, true)}
                      className={`p-1.5 rounded-full transition-colors ${row.isAbsent ? 'bg-slate-700 text-white' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}
                      title="利用無しに設定"
                    >
                      <UserX size={18} />
                    </button>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text" inputMode="decimal" disabled={row.isAbsent}
                        placeholder="365"
                        className={`w-full text-center border rounded py-1.5 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all ${getStatusClass('temperature', row.temperature || '')}`}
                        value={row.temperature || ''}
                        onChange={(e) => handleChange(res.id, 'temperature', e.target.value)}
                        onBlur={() => triggerAutoSave(res.id)}
                      />
                      <span className="absolute bottom-0 left-0 right-0 text-[10px] text-center text-slate-400 truncate">前回:{prev?.temperature || '-'}</span>
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <div className="flex items-center gap-1">
                        <input
                          type="text" inputMode="numeric" disabled={row.isAbsent}
                          className={`w-full text-center border rounded py-1.5 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all ${getStatusClass('systolic', row.systolic || '')}`}
                          value={row.systolic || ''}
                          onChange={(e) => handleChange(res.id, 'systolic', e.target.value)}
                          onBlur={() => triggerAutoSave(res.id)}
                        />
                        <span className="text-slate-400">/</span>
                        <input
                          type="text" inputMode="numeric" disabled={row.isAbsent}
                          className={`w-full text-center border rounded py-1.5 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all ${getStatusClass('diastolic', row.diastolic || '')}`}
                          value={row.diastolic || ''}
                          onChange={(e) => handleChange(res.id, 'diastolic', e.target.value)}
                          onBlur={() => triggerAutoSave(res.id)}
                        />
                      </div>
                      <span className="absolute bottom-0 left-0 right-0 text-[10px] text-center text-slate-400 truncate">前回:{prev ? `${prev.systolic}/${prev.diastolic}` : '-'}</span>
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text" inputMode="numeric" disabled={row.isAbsent}
                        className={`w-full text-center border rounded py-1.5 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all ${getStatusClass('pulse', row.pulse || '')}`}
                        value={row.pulse || ''}
                        onChange={(e) => handleChange(res.id, 'pulse', e.target.value)}
                        onBlur={() => triggerAutoSave(res.id)}
                      />
                      <span className="absolute bottom-0 left-0 right-0 text-[10px] text-center text-slate-400 truncate">前回:{prev?.pulse || '-'}</span>
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="relative pb-5">
                      <input
                        type="text" inputMode="numeric" disabled={row.isAbsent}
                        className={`w-full text-center border rounded py-1.5 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all ${getStatusClass('spo2', row.spo2 || '')}`}
                        value={row.spo2 || ''}
                        onChange={(e) => handleChange(res.id, 'spo2', e.target.value)}
                        onBlur={() => triggerAutoSave(res.id)}
                      />
                      <span className="absolute bottom-0 left-0 right-0 text-[10px] text-center text-slate-400 truncate">前回:{prev?.spo2 || '-'}</span>
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <div className="flex gap-1 justify-center">
                      {['mealMorning', 'mealNoon', 'mealNight'].map((time) => {
                        const meal = (row[time as keyof VitalRecord] as Meal) || { main: 10, side: 10 };
                        return (
                          <div key={time} className="flex flex-col items-center gap-0.5 border p-1 rounded bg-slate-50 text-[10px]">
                            <span className="font-bold">{time === 'mealMorning' ? '朝' : time === 'mealNoon' ? '昼' : '晩'}</span>
                            <div className="flex gap-0.5">
                              <input 
                                type="text" inputMode="numeric" disabled={row.isAbsent} 
                                className="w-6 text-center border rounded py-0.5 font-bold" 
                                value={meal.main} 
                                onChange={(e) => handleMealChange(res.id, time as any, 'main', parseInt(e.target.value) || 0)} 
                              />
                              <input 
                                type="text" inputMode="numeric" disabled={row.isAbsent} 
                                className="w-6 text-center border border-blue-200 bg-blue-50 rounded py-0.5 font-bold" 
                                value={meal.side} 
                                onChange={(e) => handleMealChange(res.id, time as any, 'side', parseInt(e.target.value) || 0)} 
                              />
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </td>
                  <td className="px-2 py-3">
                    <input 
                      type="text" inputMode="numeric" disabled={row.isAbsent} 
                      className="w-full text-center border rounded py-1.5 font-bold" 
                      value={row.bowelCount || '0'} 
                      onChange={(e) => handleChange(res.id, 'bowelCount', e.target.value)} 
                      onBlur={() => triggerAutoSave(res.id)}
                    />
                  </td>
                  <td className="px-2 py-3">
                    <input 
                      type="text" disabled={row.isAbsent} 
                      className="w-full border rounded py-1.5 px-2 text-xs focus:ring-2 focus:ring-blue-500 outline-none" 
                      value={row.note || ''} 
                      onChange={(e) => handleChange(res.id, 'note', e.target.value)} 
                      onBlur={() => triggerAutoSave(res.id)}
                      placeholder="..." 
                    />
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 flex gap-3 no-print">
        <AlertCircle className="text-blue-500 shrink-0" />
        <div className="text-xs text-blue-700 space-y-1">
          <p><b>自動小数点入力:</b> 体温を「365」と打つと自動で「36.5」になります。</p>
          <p><b>低血圧アラート:</b> 血圧が低い場合（100以下など）も色が変わって強調されます。</p>
          <p><b>自動保存モード:</b> 入力内容は即座に保存されます。</p>
        </div>
      </div>
    </div>
  );
};

export default BatchInputTable;

import React, { useState, useMemo, useEffect } from 'react';
import { THRESHOLDS } from '../constants';
import { VitalRecord, Resident } from '../types';
import { User, Printer, FileText, TrendingUp, Calendar, Clock } from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';

interface IndividualHistoryProps {
  records: VitalRecord[];
  residents: Resident[];
  facilityName: string;
}

const IndividualHistory: React.FC<IndividualHistoryProps> = ({ records, residents, facilityName }) => {
  const [selectedId, setSelectedId] = useState(residents[0]?.id || '');

  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const formatLocalDate = (date: Date) => {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  };

  useEffect(() => {
    const userRecords = records.filter(r => r.residentId === selectedId);

    if (userRecords.length > 0) {
      const sortedDates = userRecords.map(r => r.date).sort();
      setStartDate(sortedDates[0]);
      setEndDate(sortedDates[sortedDates.length - 1]);
    } else {
      const now = new Date();
      const firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
      const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);
      setStartDate(formatLocalDate(firstDay));
      setEndDate(formatLocalDate(lastDay));
    }
  }, [selectedId, records]);

  const filteredRecords = useMemo(() => {
    return records
      .filter(r => r.residentId === selectedId && r.date >= startDate && r.date <= endDate)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [records, selectedId, startDate, endDate]);

  const resident = useMemo(() => 
    residents.find(r => r.id === selectedId) || residents[0], 
    [selectedId, residents]
  );

  const chartData = useMemo(() => {
    return filteredRecords.filter(r => !r.isAbsent).map(r => ({
      date: r.date.split('-').slice(1).join('/'),
      temp: parseFloat(r.temperature) || null,
      systolic: parseInt(r.systolic) || null,
      diastolic: parseInt(r.diastolic) || null,
      pulse: parseInt(r.pulse) || null,
    }));
  }, [filteredRecords]);

  const setRange = (type: 'this_month' | 'last_month' | 'last_90') => {
    const now = new Date();
    if (type === 'this_month') {
      const start = new Date(now.getFullYear(), now.getMonth(), 1);
      const end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
      setStartDate(formatLocalDate(start));
      setEndDate(formatLocalDate(end));
    } else if (type === 'last_month') {
      const start = new Date(now.getFullYear(), now.getMonth() - 1, 1);
      const end = new Date(now.getFullYear(), now.getMonth(), 0);
      setStartDate(formatLocalDate(start));
      setEndDate(formatLocalDate(end));
    } else if (type === 'last_90') {
      const startD = new Date();
      startD.setDate(startD.getDate() - 90);
      setStartDate(formatLocalDate(startD));
      setEndDate(formatLocalDate(now));
    }
  };

  const handlePrint = () => {
    window.focus();
    window.print();
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 rounded-xl shadow-sm border no-print space-y-4">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
          <div className="flex flex-col md:flex-row items-center gap-4 w-full xl:w-auto">
            <div className="flex items-center gap-3 w-full md:w-64">
              <User className="text-slate-400 shrink-0" size={20} />
              <select 
                value={selectedId}
                onChange={(e) => setSelectedId(e.target.value)}
                className="w-full border rounded-md px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none text-sm font-medium"
              >
                {residents.map(res => <option key={res.id} value={res.id}>{res.roomNumber} - {res.name}</option>)}
              </select>
            </div>
            <div className="flex items-center h-10 bg-slate-50 px-2 rounded-lg border border-slate-200">
              <Calendar size={18} className="text-slate-400 shrink-0" />
              <input 
                type="date" 
                value={startDate} 
                onChange={(e) => setStartDate(e.target.value)} 
                className="bg-transparent border-none px-2 py-0 text-xs font-medium focus:ring-0 cursor-pointer h-full" 
              />
              <span className="text-slate-300 font-bold px-1 select-none">〜</span>
              <input 
                type="date" 
                value={endDate} 
                onChange={(e) => setEndDate(e.target.value)} 
                className="bg-transparent border-none px-2 py-0 text-xs font-medium focus:ring-0 cursor-pointer h-full" 
              />
            </div>
          </div>
          <button 
            type="button"
            onClick={handlePrint} 
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-900 text-white px-5 py-2.5 rounded-lg text-sm font-semibold shadow-sm transition-all active:scale-95"
          >
            <Printer size={18} /> 印刷 / PDF出力
          </button>
        </div>

        <div className="flex flex-wrap items-center gap-2 pt-2 border-t border-slate-100">
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1">
            <Clock size={12} /> 期間ショートカット:
          </span>
          <button onClick={() => setRange('this_month')} className="px-3 py-1 bg-white border border-slate-200 hover:border-blue-400 hover:text-blue-600 rounded-full text-xs transition-all shadow-sm">今月</button>
          <button onClick={() => setRange('last_month')} className="px-3 py-1 bg-white border border-slate-200 hover:border-blue-400 hover:text-blue-600 rounded-full text-xs transition-all shadow-sm">先月</button>
          <button onClick={() => setRange('last_90')} className="px-3 py-1 bg-white border border-slate-200 hover:border-blue-400 hover:text-blue-600 rounded-full text-xs transition-all shadow-sm">過去90日</button>
        </div>
      </div>

      {filteredRecords.length > 0 && chartData.length > 0 && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 no-print">
          <div className="bg-white p-6 rounded-xl border shadow-sm">
            <h3 className="text-xs font-bold mb-4 flex items-center gap-2 text-slate-500 uppercase tracking-wider"><TrendingUp size={14} /> 血圧・脈拍推移</h3>
            <div className="h-64"><ResponsiveContainer><LineChart data={chartData}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="date" fontSize={10} /><YAxis fontSize={10} domain={['dataMin - 10', 'dataMax + 10']} /><Tooltip /><Legend iconType="circle" wrapperStyle={{ fontSize: '10px' }} /><Line type="monotone" dataKey="systolic" stroke="#ef4444" name="血圧(上)" strokeWidth={2} dot={{ r: 3 }} /><Line type="monotone" dataKey="diastolic" stroke="#3b82f6" name="血圧(下)" strokeWidth={2} dot={{ r: 3 }} /><Line type="monotone" dataKey="pulse" stroke="#10b981" name="脈拍" strokeWidth={1} strokeDasharray="5 5" dot={{ r: 2 }} /></LineChart></ResponsiveContainer></div>
          </div>
          <div className="bg-white p-6 rounded-xl border shadow-sm">
            <h3 className="text-xs font-bold mb-4 flex items-center gap-2 text-slate-500 uppercase tracking-wider"><TrendingUp size={14} /> 体温推移</h3>
            <div className="h-64"><ResponsiveContainer><LineChart data={chartData}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="date" fontSize={10} /><YAxis fontSize={10} domain={[35, 38]} /><Tooltip /><Legend iconType="circle" wrapperStyle={{ fontSize: '10px' }} /><Line type="monotone" dataKey="temp" stroke="#f59e0b" name="体温(℃)" strokeWidth={3} dot={{ r: 4 }} /></LineChart></ResponsiveContainer></div>
          </div>
        </div>
      )}

      <div className="bg-white p-8 rounded-xl shadow-sm border min-h-[800px] print:shadow-none print:border-none print:p-0">
        <div className="border-b-2 border-slate-900 pb-4 mb-6 flex justify-between items-end">
          <div>
            <h2 className="text-3xl font-bold text-slate-900 tracking-tight">月間バイタル管理表</h2>
            <p className="text-slate-500 mt-1 font-medium">施設名: {facilityName}</p>
          </div>
          <div className="text-right">
            <p className="text-xl font-bold">氏名: {resident?.name} 様</p>
            <p className="text-sm text-slate-500">居室: {resident?.roomNumber}号室</p>
            <p className="text-[10px] text-slate-400 mt-1 tracking-wider font-mono">{startDate} 〜 {endDate}</p>
          </div>
        </div>

        {filteredRecords.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-slate-300"><FileText size={64} className="mb-4 opacity-10" /><p>指定された期間内に記録データがありません。</p></div>
        ) : (
          <table className="w-full border-collapse border border-slate-300 text-xs">
            <thead>
              <tr className="bg-slate-50">
                <th className="border border-slate-300 px-2 py-2 w-24 text-center">日付</th>
                <th className="border border-slate-300 px-2 py-2 text-center">体温</th>
                <th className="border border-slate-300 px-2 py-2 text-center">血圧 (上/下)</th>
                <th className="border border-slate-300 px-2 py-2 text-center">脈拍</th>
                <th className="border border-slate-300 px-2 py-2 text-center">SpO2</th>
                <th className="border border-slate-300 px-2 py-2 text-center">食事(朝/昼/晩)</th>
                <th className="border border-slate-300 px-2 py-2 text-center">排便</th>
                <th className="border border-slate-300 px-2 py-2 text-left">備考</th>
              </tr>
            </thead>
            <tbody>
              {[...filteredRecords].reverse().map((rec, i) => {
                const isHighTemp = parseFloat(rec.temperature) >= THRESHOLDS.STOP.TEMP;
                const isBPHigh = parseFloat(rec.systolic) >= THRESHOLDS.STOP.BP_SYS;
                const isBPLow = parseFloat(rec.systolic) <= THRESHOLDS.STOP.BP_SYS_LOW && rec.systolic !== '';
                const isPulseAbnormal = parseInt(rec.pulse) >= THRESHOLDS.STOP.PULSE_HIGH || parseInt(rec.pulse) <= THRESHOLDS.STOP.PULSE_LOW;
                const isSpo2Low = parseFloat(rec.spo2) < THRESHOLDS.STOP.SPO2 && rec.spo2 !== '';

                return (
                  <tr key={i} className={`text-center ${rec.isAbsent ? 'bg-slate-50 text-slate-400 italic' : ''}`}>
                    <td className="border border-slate-300 px-2 py-2 font-medium">{rec.date}</td>
                    {rec.isAbsent ? <td colSpan={7} className="border border-slate-300 px-4 py-2 text-left">利用無し {rec.note && <span className="ml-2">({rec.note})</span>}</td> : <>
                      <td className={`border border-slate-300 px-2 py-2 ${isHighTemp ? 'text-red-600 font-bold bg-red-50' : ''}`}>{rec.temperature}</td>
                      <td className={`border border-slate-300 px-2 py-2 ${(isBPHigh || isBPLow) ? 'text-red-600 font-bold bg-red-50' : ''}`}>{rec.systolic} / {rec.diastolic}</td>
                      <td className={`border border-slate-300 px-2 py-2 ${isPulseAbnormal ? 'text-red-600 font-bold bg-red-50' : ''}`}>{rec.pulse}</td>
                      <td className={`border border-slate-300 px-2 py-2 ${isSpo2Low ? 'text-red-600 font-bold bg-red-50' : ''}`}>{rec.spo2}%</td>
                      <td className="border border-slate-300 px-1 py-1 text-[10px]">
                        <div>朝 {rec.mealMorning.main}/{rec.mealMorning.side}</div>
                        <div>昼 {rec.mealNoon.main}/{rec.mealNoon.side}</div>
                        <div>晩 {rec.mealNight.main}/{rec.mealNight.side}</div>
                      </td>
                      <td className="border border-slate-300 px-2 py-2">{rec.bowelCount}</td>
                      <td className="border border-slate-300 px-2 py-2 text-left max-w-xs truncate">{rec.note}</td>
                    </>}
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

