import React, { useState, useEffect } from 'react';
import { Resident } from '../types';
import { Plus, Trash2, Save, UserCheck, Building, RotateCcw, UserMinus, ChevronUp, ChevronDown } from 'lucide-react';
import { INITIAL_RESIDENTS } from '../constants';

interface ResidentMasterProps {
  residents: Resident[];
  onUpdate: (residents: Resident[]) => void;
  facilityName: string;
  onFacilityNameUpdate: (name: string) => void;
}

const ResidentMaster: React.FC<ResidentMasterProps> = ({ 
  residents, 
  onUpdate, 
  facilityName, 
  onFacilityNameUpdate 
}) => {
  // ローカルステートで編集内容を保持
  const [localResidents, setLocalResidents] = useState<Resident[]>([]);
  const [localFacilityName, setLocalFacilityName] = useState<string>('');
  const [isDirty, setIsDirty] = useState(false);

  // 初回および親データの変更時に同期
  useEffect(() => {
    setLocalResidents([...residents]);
    setIsDirty(false);
  }, [residents]);

  useEffect(() => {
    setLocalFacilityName(facilityName);
  }, [facilityName]);

  const handleUpdate = (id: string, field: keyof Resident, value: string) => {
    setLocalResidents(prev => prev.map(r => r.id === id ? { ...r, [field]: value } : r));
    setIsDirty(true);
  };

  const handleAdd = () => {
    const newId = `res-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    const newResident: Resident = { 
      id: newId, 
      name: '', 
      roomNumber: '' 
    };
    setLocalResidents(prev => [...prev, newResident]);
    setIsDirty(true);
  };

  const handleRemove = (id: string) => {
    if (window.confirm('この利用者をリストから削除しますか？\n（「設定を保存」を押すまで確定されません）')) {
      const filtered = localResidents.filter(r => r.id !== id);
      setLocalResidents(filtered);
      setIsDirty(true);
    }
  };

  const handleMove = (index: number, direction: 'up' | 'down') => {
    const newIndex = direction === 'up' ? index - 1 : index + 1;
    if (newIndex < 0 || newIndex >= localResidents.length) return;

    const updated = [...localResidents];
    const temp = updated[index];
    updated[index] = updated[newIndex];
    updated[newIndex] = temp;

    setLocalResidents(updated);
    setIsDirty(true);
  };

  const handleClearAll = () => {
    if (window.confirm('すべての利用者を削除しますか？\n（この操作は「設定を保存」を押すまで確定されません）')) {
      setLocalResidents([]);
      setIsDirty(true);
    }
  };

  const handleResetToDefault = () => {
    if (window.confirm('利用者リストを初期状態（29名のサンプル）に戻しますか？\n（この操作は「設定を保存」を押すまで確定されません）')) {
      setLocalResidents([...INITIAL_RESIDENTS]);
      setIsDirty(true);
    }
  };

  const handleSave = () => {
    // 保存処理の実行
    onUpdate([...localResidents]);
    onFacilityNameUpdate(localFacilityName);
    setIsDirty(false);

    // UIへの通知
    alert('マスタ設定を保存し、データベースを更新しました。');
  };

  return (
    <div className="space-y-6">
      {/* System Settings Section */}
      <div className="bg-white p-6 rounded-xl border shadow-sm">
        <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2 mb-4">
          <Building size={20} className="text-blue-600" />
          施設基本設定
        </h2>
        <div className="max-w-md">
          <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">施設名称</label>
          <input 
            type="text" 
            value={localFacilityName}
            onChange={(e) => {
              setLocalFacilityName(e.target.value);
              setIsDirty(true);
            }}
            placeholder="施設名を入力してください"
            className="w-full border rounded-md px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none font-medium"
          />
        </div>
      </div>

      {/* Resident Master Section */}
      <div className="bg-white p-6 rounded-xl border shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-800">利用者マスタ設定</h2>
          <p className="text-sm text-slate-500">入所者の氏名と居室番号を管理します。（現在: {localResidents.length}名）</p>
        </div>
        <div className="flex flex-wrap gap-2 w-full md:w-auto">
          <button 
            type="button"
            onClick={handleAdd}
            className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2.5 rounded-lg font-semibold transition-all active:scale-95"
          >
            <Plus size={18} />
            新規追加
          </button>
          <button 
            type="button"
            onClick={handleSave}
            className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-2.5 rounded-lg font-semibold transition-all shadow-md active:scale-95 ${
              isDirty ? 'bg-blue-600 hover:bg-blue-700 text-white' : 'bg-slate-200 text-slate-500 cursor-not-allowed'
            }`}
            disabled={!isDirty}
          >
            <Save size={18} />
            設定を保存
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl border shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider w-20">並替</th>
                <th className="px-4 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider w-32">居室番号</th>
                <th className="px-4 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">氏名</th>
                <th className="px-6 py-3 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider w-24">操作</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-slate-200">
              {localResidents.map((res, index) => (
                <tr key={res.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-3 whitespace-nowrap">
                    <div className="flex flex-col gap-0.5">
                      <button 
                        type="button" 
                        onClick={() => handleMove(index, 'up')}
                        disabled={index === 0}
                        className={`p-0.5 rounded transition-colors ${index === 0 ? 'text-slate-200' : 'text-slate-400 hover:bg-slate-200 hover:text-slate-700'}`}
                      >
                        <ChevronUp size={16} />
                      </button>
                      <button 
                        type="button" 
                        onClick={() => handleMove(index, 'down')}
                        disabled={index === localResidents.length - 1}
                        className={`p-0.5 rounded transition-colors ${index === localResidents.length - 1 ? 'text-slate-200' : 'text-slate-400 hover:bg-slate-200 hover:text-slate-700'}`}
                      >
                        <ChevronDown size={16} />
                      </button>
                    </div>
                  </td>
                  <td className="px-4 py-3 whitespace-nowrap">
                    <input 
                      type="text" 
                      value={res.roomNumber}
                      placeholder="居室"
                      onChange={(e) => handleUpdate(res.id, 'roomNumber', e.target.value)}
                      className="w-full border border-slate-200 rounded px-2 py-1.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                    />
                  </td>
                  <td className="px-4 py-3 whitespace-nowrap">
                    <input 
                      type="text" 
                      value={res.name}
                      placeholder="氏名を入力"
                      onChange={(e) => handleUpdate(res.id, 'name', e.target.value)}
                      className="w-full border border-slate-200 rounded px-2 py-1.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                    />
                  </td>
                  <td className="px-6 py-3 whitespace-nowrap text-right">
                    <button 
                      type="button"
                      onClick={() => handleRemove(res.id)}
                      title="削除"
                      className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-all"
                    >
                      <Trash2 size={18} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {localResidents.length === 0 && (
          <div className="py-20 text-center text-slate-400">
             <UserCheck size={48} className="mx-auto mb-4 opacity-20" />
             <p>利用者が登録されていません。</p>
             <button type="button" onClick={handleAdd} className="mt-4 text-blue-600 hover:underline text-sm font-bold">最初の利用者を追加する</button>
          </div>
        )}
      </div>

      <div className="flex flex-col sm:flex-row gap-3 pt-4 border-t border-slate-200 no-print">
        <button 
          type="button"
          onClick={handleResetToDefault}
          className="flex items-center justify-center gap-2 text-xs text-slate-500 hover:text-slate-800 bg-slate-100 hover:bg-slate-200 px-4 py-2 rounded-lg transition-all"
        >
          <RotateCcw size={14} />
          初期状態に戻す
        </button>
        <button 
          type="button"
          onClick={handleClearAll}
          className="flex items-center justify-center gap-2 text-xs text-red-500 hover:text-red-700 bg-red-50 hover:bg-red-100 px-4 py-2 rounded-lg transition-all"
        >
          <UserMinus size={14} />
          全員削除
        </button>
      </div>

      <div className="bg-amber-50 border border-amber-200 p-4 rounded-lg">
        <p className="text-xs text-amber-800 leading-relaxed font-medium">
          ※ <b>並べ替え・追加・削除</b>の操作後は、必ず右上の<b>「設定を保存」</b>ボタンを押してください。保存することで一括入力画面や個人履歴にも順番が反映されます。
        </p>
      </div>
    </div>
  );
};

