import React, { useMemo } from 'react';
import { VitalRecord, Resident } from '../types';
import { THRESHOLDS } from '../constants';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Activity, AlertTriangle, CheckCircle2, Thermometer } from 'lucide-react';

interface DashboardProps {
  records: VitalRecord[];
  residents: Resident[];
}

const Dashboard: React.FC<DashboardProps> = ({ records, residents }) => {
  const stats = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    const latestRecords = records.filter(r => r.date === todayStr);

    const highTemp = latestRecords.filter(r => parseFloat(r.temperature) >= THRESHOLDS.STOP.TEMP).length;
    const highBP = latestRecords.filter(r => parseFloat(r.systolic) >= THRESHOLDS.STOP.BP_SYS).length;
    const lowSpO2 = latestRecords.filter(r => parseFloat(r.spo2) < THRESHOLDS.STOP.SPO2 && r.spo2 !== '').length;

    return {
      todayCount: latestRecords.length,
      highTemp,
      highBP,
      lowSpO2
    };
  }, [records]);

  // Chart data: Temperature distribution for today
  const chartData = useMemo(() => {
    const bins = [
      { name: '35.0-', count: 0 },
      { name: '36.0-', count: 0 },
      { name: '36.5-', count: 0 },
      { name: '37.0-', count: 0 },
      { name: '37.5+', count: 0 },
    ];

    records.filter(r => r.date === new Date().toISOString().split('T')[0]).forEach(r => {
      const t = parseFloat(r.temperature);
      if (t >= 37.5) bins[4].count++;
      else if (t >= 37.0) bins[3].count++;
      else if (t >= 36.5) bins[2].count++;
      else if (t >= 36.0) bins[1].count++;
      else bins[0].count++;
    });

    return bins;
  }, [records]);

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-5 rounded-xl border shadow-sm flex items-center gap-4">
          <div className="bg-blue-100 p-3 rounded-lg text-blue-600">
            <Activity size={24} />
          </div>
          <div>
            <p className="text-xs text-slate-500 font-semibold">本日の入力済</p>
            <p className="text-2xl font-bold">{stats.todayCount} <span className="text-sm font-normal text-slate-400">/ {residents.length} 名</span></p>
          </div>
        </div>

        <div className="bg-white p-5 rounded-xl border shadow-sm flex items-center gap-4">
          <div className="bg-red-100 p-3 rounded-lg text-red-600">
            <Thermometer size={24} />
          </div>
          <div>
            <p className="text-xs text-slate-500 font-semibold">発熱 ({THRESHOLDS.STOP.TEMP.toFixed(1)}℃↑)</p>
            <p className="text-2xl font-bold text-red-600">{stats.highTemp} <span className="text-sm font-normal text-slate-400">名</span></p>
          </div>
        </div>

        <div className="bg-white p-5 rounded-xl border shadow-sm flex items-center gap-4">
          <div className="bg-orange-100 p-3 rounded-lg text-orange-600">
            <AlertTriangle size={24} />
          </div>
          <div>
            <p className="text-xs text-slate-500 font-semibold">高血圧 ({THRESHOLDS.STOP.BP_SYS}↑)</p>
            <p className="text-2xl font-bold text-orange-600">{stats.highBP} <span className="text-sm font-normal text-slate-400">名</span></p>
          </div>
        </div>

        <div className="bg-white p-5 rounded-xl border shadow-sm flex items-center gap-4">
          <div className="bg-green-100 p-3 rounded-lg text-green-600">
            <CheckCircle2 size={24} />
          </div>
          <div>
            <p className="text-xs text-slate-500 font-semibold">要注意 (SpO2 {THRESHOLDS.STOP.SPO2}↓)</p>
            <p className="text-2xl font-bold text-slate-800">{stats.lowSpO2} <span className="text-sm font-normal text-slate-400">名</span></p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl border shadow-sm">
          <h3 className="text-lg font-bold mb-6 text-slate-800">本日の体温分布</h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" />
                <YAxis allowDecimals={false} />
                <Tooltip />
                <Bar dataKey="count" fill="#3b82f6" radius={[4, 4, 0, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index === 4 ? '#ef4444' : '#3b82f6'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl border shadow-sm">
          <h3 className="text-lg font-bold mb-4 text-slate-800">システムの活用方法</h3>
          <div className="space-y-4">
            <div className="flex gap-4 items-start">
              <div className="bg-slate-100 w-8 h-8 rounded-full flex items-center justify-center font-bold text-slate-600 shrink-0">1</div>
              <div>
                <p className="font-semibold text-sm">一括入力</p>
                <p className="text-xs text-slate-500">朝の忙しい時間でも、登録された利用者の数値をリスト形式で素早く入力できます。テンキー入力とタブキーを活用すると便利です。</p>
              </div>
            </div>
            <div className="flex gap-4 items-start">
              <div className="bg-slate-100 w-8 h-8 rounded-full flex items-center justify-center font-bold text-slate-600 shrink-0">2</div>
              <div>
                <p className="font-semibold text-sm">自動仕分け</p>
                <p className="text-xs text-slate-500">入力内容は自動保存され、個人別の履歴として蓄積されます。マスタで名前や順序を変更しても、履歴データと連動します。</p>
              </div>
            </div>
            <div className="flex gap-4 items-start">
              <div className="bg-slate-100 w-8 h-8 rounded-full flex items-center justify-center font-bold text-slate-600 shrink-0">3</div>
              <div>
                <p className="font-semibold text-sm">レポート作成</p>
                <p className="text-xs text-slate-500">受診時やご家族への報告用に、個人別履歴画面からいつでも綺麗なフォーマットで印刷またはPDF出力が可能です。</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { AppView, VitalRecord, Resident } from './types';
import BatchInputTable from './components/BatchInputTable';
import IndividualHistory from './components/IndividualHistory';
import Dashboard from './components/Dashboard';
import ResidentMaster from './components/ResidentMaster';
import { LayoutGrid, Users, ClipboardList, Info, Settings } from 'lucide-react';
import { INITIAL_RESIDENTS } from './constants';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.BATCH_INPUT);
  const [records, setRecords] = useState<VitalRecord[]>([]);
  const [residents, setResidents] = useState<Resident[]>(INITIAL_RESIDENTS);
  const [facilityName, setFacilityName] = useState<string>('陽光ケアホーム');

  useEffect(() => {
    const savedRecords = localStorage.getItem('vital_records');
    if (savedRecords) {
      setRecords(JSON.parse(savedRecords));
    }

    const savedResidents = localStorage.getItem('residents_master');
    if (savedResidents) {
      setResidents(JSON.parse(savedResidents));
    }

    const savedFacility = localStorage.getItem('facility_name');
    if (savedFacility) {
      setFacilityName(savedFacility);
    }
  }, []);

  /**
   * レコードを保存または更新する（日付と利用者IDが一致すれば上書き）
   */
  const saveBatchRecords = (newRecords: VitalRecord[]) => {
    setRecords(prev => {
      const next = [...prev];
      newRecords.forEach(nr => {
        const idx = next.findIndex(r => r.residentId === nr.residentId && r.date === nr.date);
        if (idx > -1) {
          next[idx] = nr; // 既存データを更新（上書き）
        } else {
          next.push(nr); // 新規データを追加
        }
      });
      localStorage.setItem('vital_records', JSON.stringify(next));
      return next;
    });
  };

  const updateResidents = (newResidents: Resident[]) => {
    setResidents(newResidents);
    localStorage.setItem('residents_master', JSON.stringify(newResidents));
  };

  const updateFacilityName = (name: string) => {
    setFacilityName(name);
    localStorage.setItem('facility_name', name);
  };

  return (
    <div className="min-h-screen flex flex-col">
      <header className="bg-white border-b sticky top-0 z-50 no-print">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-2">
              <div className="bg-blue-600 p-2 rounded-lg">
                <ClipboardList className="text-white w-6 h-6" />
              </div>
              <h1 className="text-xl font-bold text-slate-800 tracking-tight">VitalSign Pro</h1>
            </div>
            <nav className="flex space-x-1 sm:space-x-4">
              <button
                onClick={() => setCurrentView(AppView.BATCH_INPUT)}
                className={`flex items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  currentView === AppView.BATCH_INPUT ? 'bg-blue-50 text-blue-700' : 'text-slate-500 hover:bg-slate-50'
                }`}
              >
                <LayoutGrid size={18} />
                <span className="hidden sm:inline">一括入力</span>
              </button>
              <button
                onClick={() => setCurrentView(AppView.INDIVIDUAL_HISTORY)}
                className={`flex items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  currentView === AppView.INDIVIDUAL_HISTORY ? 'bg-blue-50 text-blue-700' : 'text-slate-500 hover:bg-slate-50'
                }`}
              >
                <Users size={18} />
                <span className="hidden sm:inline">個人履歴</span>
              </button>
              <button
                onClick={() => setCurrentView(AppView.DASHBOARD)}
                className={`flex items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  currentView === AppView.DASHBOARD ? 'bg-blue-50 text-blue-700' : 'text-slate-500 hover:bg-slate-50'
                }`}
              >
                <Info size={18} />
                <span className="hidden sm:inline">概要</span>
              </button>
              <button
                onClick={() => setCurrentView(AppView.RESIDENT_MASTER)}
                className={`flex items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  currentView === AppView.RESIDENT_MASTER ? 'bg-blue-50 text-blue-700' : 'text-slate-500 hover:bg-slate-50'
                }`}
              >
                <Settings size={18} />
                <span className="hidden sm:inline">マスタ</span>
              </button>
            </nav>
          </div>
        </div>
      </header>

      <main className="flex-1 overflow-auto p-4 sm:p-6 lg:p-8">
        <div className="max-w-7xl mx-auto h-full">
          {currentView === AppView.BATCH_INPUT && (
            <BatchInputTable onSave={saveBatchRecords} residents={residents} records={records} />
          )}
          {currentView === AppView.INDIVIDUAL_HISTORY && (
            <IndividualHistory records={records} residents={residents} facilityName={facilityName} />
          )}
          {currentView === AppView.DASHBOARD && (
            <Dashboard records={records} residents={residents} />
          )}
          {currentView === AppView.RESIDENT_MASTER && (
            <ResidentMaster 
              residents={residents} 
              onUpdate={updateResidents} 
              facilityName={facilityName}
              onFacilityNameUpdate={updateFacilityName}
            />
          )}
        </div>
      </main>

      <footer className="bg-white border-t py-4 text-center text-xs text-slate-400 no-print">
        &copy; 2024 VitalSign Pro - 介護現場効率化システム
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Resident } from '../types';
import { Plus, Trash2, Save, UserCheck, Building, RotateCcw, UserMinus, ChevronUp, ChevronDown, AlertCircle } from 'lucide-react';
import { INITIAL_RESIDENTS } from '../constants';

interface ResidentMasterProps {
  residents: Resident[];
  onUpdate: (residents: Resident[]) => void;
  facilityName: string;
  onFacilityNameUpdate: (name: string) => void;
}

const ResidentMaster: React.FC<ResidentMasterProps> = ({ 
  residents, 
  onUpdate, 
  facilityName, 
  onFacilityNameUpdate 
}) => {
  // 編集中のデータを保持するローカルステート
  const [localResidents, setLocalResidents] = useState<Resident[]>([]);
  const [localFacilityName, setLocalFacilityName] = useState<string>(facilityName);
  const [isDirty, setIsDirty] = useState(false);

  // 保存完了フラグ（保存後にプロップスと強制同期させるため）
  const lastSavedRef = useRef(JSON.stringify(residents));

  // 初回読み込み、および「保存完了後」にプロップスと同期する
  useEffect(() => {
    const currentPropsStr = JSON.stringify(residents);
    // ユーザーが編集を開始していない、または親のデータが実際に変わった（保存された）場合のみ同期
    if (!isDirty || lastSavedRef.current !== currentPropsStr) {
      setLocalResidents([...residents]);
      lastSavedRef.current = currentPropsStr;
      setIsDirty(false);
    }
  }, [residents, isDirty]);

  // 施設名の同期
  useEffect(() => {
    setLocalFacilityName(facilityName);
  }, [facilityName]);

  const handleUpdate = (id: string, field: keyof Resident, value: string) => {
    setLocalResidents(prev => prev.map(r => r.id === id ? { ...r, [field]: value } : r));
    setIsDirty(true);
  };

  const handleAdd = () => {
    const newId = `res-temp-${Date.now()}-${Math.floor(Math.random() * 10000)}`;
    const newResident: Resident = { 
      id: newId, 
      name: '', 
      roomNumber: '' 
    };
    // 関数型アップデートを使用して確実に最新のステートに反映
    setLocalResidents(prev => [...prev, newResident]);
    setIsDirty(true);
  };

  const handleRemove = (id: string) => {
    // ユーザーへの確認
    if (window.confirm('この利用者をリストから削除しますか？\n（「設定を保存」を押すまで確定されません）')) {
      // 即座にフィルタリングしてステートを更新
      setLocalResidents(prev => prev.filter(r => r.id !== id));
      setIsDirty(true);
    }
  };

  const handleMove = (index: number, direction: 'up' | 'down') => {
    const nextIndex = direction === 'up' ? index - 1 : index + 1;
    if (nextIndex < 0 || nextIndex >= localResidents.length) return;

    setLocalResidents(prev => {
      const updated = [...prev];
      const temp = updated[index];
      updated[index] = updated[nextIndex];
      updated[nextIndex] = temp;
      return updated;
    });
    setIsDirty(true);
  };

  const handleSave = () => {
    // 空の名前がある場合は警告（任意）
    if (localResidents.some(r => !r.name.trim())) {
      if (!window.confirm('名前が空の利用者が含まれています。そのまま保存しますか？')) {
        return;
      }
    }

    // 親コンポーネントへ保存を通知
    onUpdate([...localResidents]);
    onFacilityNameUpdate(localFacilityName);

    // 保存した内容を記録し、ダーティフラグを折る
    lastSavedRef.current = JSON.stringify(localResidents);
    setIsDirty(false);

    alert('設定を保存しました。');
  };

  const handleReset = () => {
    if (window.confirm('編集内容を破棄して、最後に保存した状態に戻しますか？')) {
      setLocalResidents([...residents]);
      setIsDirty(false);
    }
  };

  const handleDefaultSample = () => {
    if (window.confirm('利用者リストを初期サンプル（29名）に戻しますか？\n（現在の編集内容は上書きされます）')) {
      setLocalResidents([...INITIAL_RESIDENTS]);
      setIsDirty(true);
    }
  };

  return (
    <div className="space-y-6">
      {/* 施設名設定 */}
